const LEGAL_CHECK_DATE = "30.08.2026";
const LEGAL_SOURCE_NOTICE = "Link verificat către forma consolidată disponibilă pe Portalul Legislativ";


const legislationActs = [
  {id:"cod",title:"OMJ nr. 2794/C/2004 — Codul deontologic",scope:"Anexa nr. 1: art. 2, 6 și 11",url:"https://legislatie.just.ro/Public/DetaliiDocumentAfis/56993",status:"integrat",articles:[
    {id:"cod-2",number:"Art. 2",heading:"Principiile conduitei profesionale",intro:"Principiile care guvernează conduita profesională a funcționarilor publici din sistemul administrației penitenciare sunt:",items:["supunerea deplină față de lege;","respectarea drepturilor persoanelor private de libertate, în condițiile prevăzute de lege;","egalitatea șanselor;","responsabilitate și imparțialitate;","eficacitate în serviciul intereselor generale ale societății;","eficiență în utilizarea resurselor;","ierarhia organizatorică și funcțională."]},
    {id:"cod-6",number:"Art. 6",heading:"Obligații profesionale",intro:"(1) În îndeplinirea atribuțiilor profesionale funcționarii publici din sistemul administrației penitenciare au obligația:",items:["a) să cunoască, să respecte Constituția și legile țării și să aplice dispozițiile legale în conformitate cu atribuțiile ce le revin, cu respectarea eticii profesionale;","b) să se comporte civilizat și demn în toate împrejurările, să manifeste stăpânire de sine, amabilitate, politețe și să vorbească respectuos și decent, într-o manieră potrivită cu funcția pe care o dețin;","c) să constituie exemple pentru subordonați, colegi și persoanele private de libertate, să creeze un climat corespunzător de muncă și să contribuie la realizarea și menținerea unei imagini pozitive a instituției;","d) să execute, cu profesionalism și în termenul stabilit, atribuțiile ce îi revin și să dovedească, în toate împrejurările, cinste, corectitudine, disciplină și respect față de șefii ierarhici, colegi și subalterni;","e) să se prezinte la serviciu într-o stare corespunzătoare, să respecte întocmai programul de muncă și să folosească timpul de lucru, resursele materiale și financiare ale instituției în mod eficient și rațional, numai pentru îndeplinirea atribuțiilor de serviciu;","f) să asigure ocrotirea bunurilor instituției și să prevină producerea oricărui prejudiciu, acționând în orice situație ca buni gospodari;","g) să respecte prevederile legale referitoare la incompatibilități și interdicții;","h) să nu interzică sau să nu împiedice exercitarea libertăților publice și a drepturilor sindicale ale funcționarilor publici din sistemul administrației penitenciare;","i) să se abțină de la exprimarea sau manifestarea convingerilor politice în exercitarea atribuțiilor de serviciu;","j) să respecte jurământul de credință depus cu ocazia numirii în funcție;","k) să nu manifeste toleranță față de abateri și să informeze autoritățile abilitate cu privire la infracțiunile de care au luat la cunoștință în exercitarea atribuțiilor de serviciu sau în legătură cu serviciul, îndeosebi a actelor de corupție;","l) să informeze șeful ierarhic despre existența unui conflict de interese privind exercitarea atribuțiilor de serviciu, în condițiile legii."],subsections:[{intro:"(2) În relațiile cu persoanele private de libertate, funcționarii publici din sistemul administrației penitenciare au următoarele obligații:",items:["a) să respecte și să protejeze drepturile și libertățile fundamentale ale persoanelor private de libertate, precum și viața, sănătatea și demnitatea acestora;","b) să prevină și să se abțină de la orice acțiune care presupune discriminarea persoanelor private de libertate sau a oricărei alte persoane pe temei de etnie, rasă, naționalitate, sex și orientare sexuală, religie, limbă, opinie sau alte temeiuri;","c) să manifeste înțelegere față de problemele persoanelor private de libertate și respect pentru dreptul acestora la exprimarea opiniilor, în limitele regulilor de ordine și disciplină stabilite în penitenciar;","d) să acționeze pentru influențarea pozitivă a comportamentului persoanelor private de libertate, atât prin exemplul personal, cât și prin încurajarea acestora de a-și asuma răspunderea pentru faptele comise și de a participa la activități specifice astfel încât, la punerea în libertate, să se poată reintegra în societate;","e) să primească și să soluționeze, cu imparțialitate și în termen legal, cererile, sesizările și plângerile persoanelor private de libertate sau ale altor persoane;","f) să sprijine persoanele private de libertate, în limita competențelor profesionale, pentru rezolvarea legală a problemelor juridice, sociale și familiale pe care le au pe timpul executării pedepselor pronunțate de instanțele de judecată, dovedind solicitudine și înțelegere."]}]},
    {id:"cod-11",number:"Art. 11",heading:"Interdicții",intro:"Funcționarilor publici din sistemul administrației penitenciare le este interzis:",items:["a) să dispună, să exercite, să instige ori să tolereze actele de tortură sau orice formă de tratament inuman ori degradant asupra persoanelor private de libertate;","b) să primească, să solicite ori să accepte, direct sau indirect, pentru sine sau pentru alte persoane, în considerarea calității oficiale, cadouri, bani, împrumuturi, orice alte valori sau servicii;","c) să uzeze de calitatea sau de funcția pe care o îndeplinesc pentru rezolvarea unor interese de ordin personal ori pentru a constrânge, a intimida sau a înșela alte persoane în scopul obținerii unor privilegii, bunuri ori servicii;","d) să stabilească relații de afaceri ori de altă natură cu persoanele private de libertate, cu persoane din lumea interlopă sau cunoscute a fi implicate în activități ilegale;","e) să intervină pentru soluționarea unor cereri sau lucrări care nu sunt de competența lor ori nu le-au fost repartizate de conducătorii ierarhici;","f) să exercite activități cu scop lucrativ care au legătură cu atribuțiile funcției publice pe care o dețin și să fie mandatari ai unor persoane în ceea ce privește efectuarea unor acte în legătură cu funcția pe care o îndeplinesc;","g) să dețină orice altă funcție publică sau privată pentru care sunt retribuiți, cu excepția funcțiilor didactice din cadrul instituțiilor de învățământ, a activităților de cercetare științifică și creație literar-artistică;","h) să recurgă la forță sau la folosirea mijloacelor de imobilizare împotriva persoanelor private de libertate, în alte condiții decât cele expres prevăzute de lege."]}
  ]},
  {id:"l145",title:"Legea nr. 145/2019",scope:"Art. 7–10, 104–105, 119–121, 133 și 140–141",url:"https://legislatie.just.ro/Public/DetaliiDocument/222277",status:"integrat",articles:[
    {id:"l145-7",number:"Art. 7",heading:"Polițiști debutanți sau definitivi",intro:"Polițiștii de penitenciare sunt debutanți sau definitivi.",items:[]},
    {id:"l145-8",number:"Art. 8",heading:"Polițiștii debutanți",intro:"Polițiștii de penitenciare debutanți sunt persoanele care ocupă, în urma concursului sau examenului, o funcție publică în sistemul administrației penitenciare, până la definitivare.",items:[]},
    {id:"l145-9",number:"Art. 9",heading:"Categorii și grade profesionale",intro:"(1) Polițiștii de penitenciare se împart în două categorii, în raport cu nivelul minim al studiilor necesare, după cum urmează:",items:["a) categoria ofițerilor - cuprinde polițiștii de penitenciare cu studii superioare, absolvite cu diplomă de licență emisă de instituții acreditate, potrivit legii;","b) categoria agenților - cuprinde polițiștii de penitenciare cu studii liceale absolvite cu diplomă de bacalaureat."],subsections:[{intro:"(2) Categoriile de polițiști de penitenciare se împart pe grade profesionale, după cum urmează: A. Categoria ofițerilor de poliție penitenciară:",items:["a) chestor șef de poliție penitenciară;","b) chestor șef adjunct de poliție penitenciară;","c) chestor principal de poliție penitenciară;","d) chestor de poliție penitenciară;","e) comisar șef de poliție penitenciară;","f) comisar de poliție penitenciară;","g) subcomisar de poliție penitenciară;","h) inspector principal de poliție penitenciară;","i) inspector de poliție penitenciară;","j) subinspector de poliție penitenciară."]},{intro:"B. Categoria agenților de poliție penitenciară:",items:["a) agent șef principal de poliție penitenciară;","b) agent șef de poliție penitenciară;","c) agent șef adjunct de poliție penitenciară;","d) agent principal de poliție penitenciară;","e) agent de poliție penitenciară."]}]},
    {id:"l145-10",number:"Art. 10",heading:"Funcții de conducere și de execuție",intro:"(1) Funcțiile polițiștilor de penitenciare sunt de conducere și de execuție.",items:["(2) Funcțiile polițiștilor de penitenciare se stabilesc prin hotărâre a Guvernului și se diferențiază în cadrul aceleiași categorii prin grad profesional și coeficient de ierarhizare."]},
    {id:"l145-104",number:"Art. 104",heading:"Drepturile polițistului de penitenciare",intro:"Polițistul de penitenciare are dreptul la:",items:["a) salariu lunar, potrivit legii;","b) ajutoare și alte drepturi bănești, ale căror cuantumuri se stabilesc prin lege;","c) uniformă și echipament specific și drepturi de hrană, în condițiile legii și ale hotărârii Guvernului;","d) asistență medicală și psihologică, medicamente, proteze și dispozitive medicale destinate recuperării unor deficiențe organice sau funcționale, în mod gratuit, în condițiile stabilite prin hotărâre a Guvernului și cu respectarea dispozițiilor legale privind plata contribuției pentru asigurările sociale de sănătate;","e) locuințe de serviciu și de intervenție, în condițiile legii;","f) concedii de odihnă, concedii de studii, învoiri plătite și concedii fără plată, în condițiile stabilite prin hotărâre a Guvernului;","g) concedii medicale, concedii de maternitate, pentru creșterea copilului până la vârsta de 2 ani sau a copilului cu handicap până la vârsta de 3 ani, concediu paternal, precum și pentru alte situații, în condițiile stabilite de lege;","h) bilete de odihnă, bilete de tratament balnear și bilete de recuperare fizică și psihică, în condițiile stabilite prin hotărâre a Guvernului;","i) pensii, în condițiile legii;","j) indemnizații de instalare, de mutare, de delegare sau detașare, precum și decontarea cheltuielilor de cazare, în condițiile stabilite de lege;","k) încadrarea activității în condiții deosebite, speciale sau alte condiții de muncă, potrivit legii;","l) portul permanent al armamentului din dotare sau achiziționat personal, în condițiile legii;","m) despăgubiri acordate din fondurile bugetare ale instituției, în cazul în care viața, sănătatea ori bunurile sale, ale soțului/soției și ale copiilor aflați în întreținerea sa sunt afectate în exercitarea atribuțiilor de serviciu sau în legătură cu acestea. Despăgubirile menționate se acordă în condițiile stabilite prin hotărâre a Guvernului;","n) tratament medical în străinătate pentru afecțiuni medicale dobândite în timpul exercitării profesiei, dacă nu pot fi tratate în țară, în condițiile stabilite prin hotărâre a Guvernului;","o) asistența juridică asigurată în mod gratuit de unitate, la cerere, prin avocat, în cazul cercetării penale, urmăririi penale sau judecării sale pentru fapte săvârșite în exercitarea atribuțiilor de serviciu, în cazurile și condițiile stabilite prin ordin al ministrului justiției. În situația în care se constată vinovăția polițistului de penitenciare, acesta este obligat să restituie toate cheltuielile efectuate de unitate."]},
    {id:"l145-105",number:"Art. 105",heading:"Decontarea cheltuielilor de transport",intro:"(1) Polițistul de penitenciare are dreptul la decontarea cheltuielilor de transport, în cazul deplasării în interes de serviciu, în cazul mutării în alte localități, în cazul deplasării de la domiciliu la locul de muncă, când domiciliază în altă localitate decât cea în care își desfășoară activitatea, în limita a 70 km dus și 70 km întors, și, o dată pe an, pentru efectuarea concediului de odihnă, precum și în alte situații, în condițiile stabilite prin hotărâre a Guvernului.",items:[],subsections:[{intro:"(2) Polițistul de penitenciare nu beneficiază de decontarea cheltuielilor de transport în cazul deplasării de la domiciliu la locul de muncă, când domiciliază în altă localitate decât cea în care își desfășoară activitatea, dacă în localitatea în care se află locul de muncă:",items:["a) acesta, soțul/soția sau copiii aflați în întreținere au o locuință proprietate personală ori, după caz, le-a fost atribuită o locuință de către autoritățile administrației publice locale;","b) acesta sau soțul/soția beneficiază de locuință de serviciu;","c) beneficiază de compensarea chiriei în condițiile art. 111."]},{intro:"(3) Polițistul de penitenciare nu beneficiază de decontarea cheltuielilor de transport în cazul deplasării de la domiciliu la locul de muncă, când domiciliază în altă localitate decât cea în care își desfășoară activitatea, dacă acesta, soțul/soția acestuia sau copiii aflați în întreținere au înstrăinat o locuință proprietate personală, în localitatea în care își desfășoară activitatea, după data încadrării în sistemul administrației penitenciare.",items:[]},{intro:"(4) În cazul deplasării cu autoturismul, polițiștilor de penitenciare li se decontează contravaloarea a 7,5 litri carburant la 100 km parcurși pe distanța cea mai scurtă dintre localități.",items:[]}]},
    {id:"l145-119",number:"Art. 119",heading:"Obligațiile polițistului de penitenciare",intro:"Polițistul de penitenciare are următoarele obligații:",items:["a) să cunoască și să respecte principiile generale prevăzute de Constituție și de celelalte legi, precum și să apere valorile democrației;","b) să respecte și să protejeze viața, sănătatea și demnitatea persoanelor private de libertate, drepturile și libertățile acestora;","c) să împiedice orice acțiune care presupune discriminare pe criterii de rasă, naționalitate, origine etnică, limbă, religie, gen, orientare sexuală, opinie, apartenență politică, avere, origine socială, vârstă, dizabilitate, boală cronică necontagioasă sau infecție HIV/SIDA ori pentru alte împrejurări de același fel;","d) să execute, cu profesionalism și în termenul stabilit, toate atribuțiile de serviciu stabilite prin fișa postului, precum și dispozițiile date de conducătorii ierarhici;","e) să fie disciplinat, respectuos și corect față de șefi, colegi sau subalterni și să respecte ierarhia conferită de funcția și gradul profesional deținute;","f) să informeze în scris conducătorii ierarhici și celelalte autorități abilitate cu privire la infracțiunile de care a luat cunoștință în exercitarea atribuțiilor de serviciu sau în legătură cu serviciul;","g) să manifeste preocupare și interes pentru perfecționarea nivelului de instruire profesională;","h) să păstreze secretul de stat și de serviciu, în condițiile legii, precum și confidențialitatea informațiilor sau documentelor care au acest caracter, în condițiile legii;","i) să se abțină de la exprimarea sau manifestarea convingerilor lui politice în exercitarea atribuțiilor ce îi revin;","j) să se conformeze dispozițiilor date de conducătorii ierarhici cărora le este subordonat direct, cu respectarea prevederilor art. 4 alin. (3);","k) să respecte întocmai programul de muncă;","l) să se prezinte la programul de muncă stabilit, precum și în afara acestuia, în situații temeinic justificate;","m) să informeze șeful ierarhic despre existența unui conflict de interese privind exercitarea atribuțiilor de serviciu, în condițiile legii;","n) să se prezinte la unitatea din care face parte, în situații de catastrofe, calamități, alarmare ca urmare a revoltelor în penitenciar, evadărilor, părăsirii locurilor de deținere sau alte tulburări de amploare ale activităților în unitățile penitenciare;","o) să acționeze, conform legii, la instituirea stării de urgență sau a stării de asediu ori în caz de mobilizare și război;","p) să depună declarațiile de avere și de interese, potrivit legii;","q) să informeze șeful ierarhic despre existența în unitatea în care își desfășoară activitatea a unor persoane private de libertate care au calitatea de soț/soție sau rude până la gradul II inclusiv cu acesta ori cu soțul/soția, în situația în care ia cunoștință de aceste situații;","r) să aducă la cunoștința compartimentului resurse umane modificările privind domiciliul, după caz, reședința, precum și schimbările intervenite în starea civilă sau date relevante din punct de vedere profesional, în termen de 15 zile de la producerea acestora."]},
    {id:"l145-120",number:"Art. 120",heading:"Interdicții",intro:"Ofițerilor și agenților din sistemul administrației penitenciare le este interzis:",items:["a) să dispună, să exercite, să instige ori să tolereze acte de tortură sau orice forme de tratament inuman ori degradant asupra persoanelor aflate în așezămintele de deținere;","b) să primească, să solicite ori să accepte, direct sau indirect, pentru ei ori pentru alte persoane, în considerarea calității lor oficiale, cadouri, bani, împrumuturi sau orice alte valori ori servicii;","c) să intervină pentru soluționarea unor cereri sau lucrări care nu sunt de competența lor ori nu le-au fost repartizate de conducătorii ierarhici sau care nu sunt activități specifice funcției pe care au fost numiți;","d) să recurgă la forță sau la folosirea mijloacelor de imobilizare împotriva persoanelor private de libertate în alte condiții decât cele expres prevăzute de lege;","e) să facă parte din partide, formațiuni sau organizații politice ori să desfășoare propagandă în favoarea acestora;","f) să adere la asociații, organizații religioase sau de altă natură, nerecunoscute potrivit legii sau interzise prin lege."]},
    {id:"l145-121",number:"Art. 121",heading:"Conflictul de interese",intro:"(1) Polițiștii de penitenciare sunt în conflict de interese dacă se află în una dintre următoarele situații:",items:["a) sunt chemați să rezolve cereri, să ia decizii sau să participe la luarea deciziilor cu privire la persoane fizice și juridice cu care sunt soț/soție, rude de gradul I sau, după caz, au relații cu caracter patrimonial;","b) sunt chemați să participe în cadrul unor comisii constituite, conform legii, din care face parte soțul/soția sau o rudă de gradul I;","c) interesele lor patrimoniale, ale soțului sau rudelor lor de gradul I pot influența deciziile pe care trebuie să le ia în exercitarea atribuțiilor de serviciu."],subsections:[{intro:"(2) Nu sunt permise raporturile ierarhice directe între polițiștii de penitenciare care sunt soți sau rude de gradul I.",items:[]},{intro:"(3) În cazul existenței unui conflict de interese, polițistul de penitenciare este obligat să se abțină de la rezolvarea cererii, luarea deciziei sau participarea la luarea unei decizii și să îl informeze de îndată pe șeful ierarhic căruia îi este subordonat direct.",items:[]}]},
    {id:"l145-133",number:"Art. 133",heading:"Încetarea raportului de serviciu",intro:"Raportul de serviciu al polițistului de penitenciare încetează în următoarele cazuri:",items:["a) deces;","b) demisie;","c) nu mai îndeplinește una dintre condițiile prevăzute la art. 11 lit. a), d), i);","d) nu mai îndeplinește condiția prevăzută la art. 11 lit. j), în măsura în care nu există nicio altă funcție în poliția penitenciară pe care să se poată realiza numirea;","e) transfer;","f) eliberarea din funcție, ca sancțiune disciplinară;","g) pensionare, în condițiile legii;","h) desființarea unității ori mutarea acesteia în altă localitate, în cazul în care ofițerul sau agentul nu acceptă să o urmeze;","i) reorganizarea unității, prin desființarea unor posturi de natura celui ocupat de ofițerul sau agentul în cauză, în cazul în care persoana refuză oferta de trecere în altă funcție;","j) nu mai îndeplinește condițiile specifice postului, în cazul în care refuză oferta conducerii unității de trecere în altă funcție;","k) ca urmare a constatării nulității actului de numire în funcție, de la data rămânerii definitive a hotărârii judecătorești prin care nulitatea a fost constatată;","l) ca urmare a declarării necorespunzător din punct de vedere profesional a polițistului debutant, conform art. 18 alin. (4);","m) la data rămânerii definitive a hotărârii judecătorești de declarare a morții polițistului de penitenciare;","n) ca urmare a interzicerii exercitării dreptului de a ocupa o funcție publică sau de a exercita profesia ori activitatea în executarea căreia a săvârșit fapta, ca pedepse complementare, sau ca urmare a interzicerii ocupării unei funcții sau a exercitării unei profesii, ca măsură de siguranță, de la data rămânerii definitive a hotărârii judecătorești prin care s-a dispus interdicția;","o) neprezentarea, în mod nejustificat, în termenul prevăzut de lege, la diagnosticarea de către un medic de specialitate sau la comisia de expertiză medico-militară, în condițiile art. 131;","p) condamnarea la o pedeapsă privativă de libertate, cu executare sau suspendarea executării pedepsei, dispusă prin hotărâre judecătorească definitivă;","q) nesoluționarea situațiilor prevăzute la art. 129 în termenul stabilit prin acest articol, dacă nu există nicio altă funcție în cadrul poliției penitenciare pe care să se poată realiza numirea;","r) alte cazuri prevăzute expres de lege."]},
    {id:"l145-140",number:"Art. 140",heading:"Abateri disciplinare",intro:"Sunt abateri disciplinare următoarele fapte:",items:["a) manifestările care aduc atingere prestigiului autorității sau instituției publice în care își desfășoară activitatea;","b) neglijență și superficialitate manifestate în îndeplinirea atribuțiilor de serviciu, a dispozițiilor legale sau a celor primite de la șefii ierarhici ori de la autoritățile anume abilitate de lege;","c) întârzierea repetată și nejustificată în îndeplinirea sarcinilor de serviciu;","d) refuzul nejustificat de a îndeplini o atribuție de serviciu cuprinsă în fișa postului;","e) manifestarea unui comportament necorespunzător față de persoanele private de libertate, care contravine legii privind executarea pedepselor, sau față de alte persoane cu care intră în contact în timpul serviciului;","f) absența nemotivată ori întârzierea repetată la serviciu;","g) părăsirea nejustificată a locului de muncă în timpul programului de lucru;","h) producerea de pagube materiale unității din care face parte sau patrimoniului Administrației Naționale a Penitenciarelor;","i) încălcarea normelor privind confidențialitatea activității sau a lucrărilor;","j) depășirea atribuțiilor de serviciu ori imixtiunea ilegală în activitatea altui polițist de penitenciare;","k) intervenția pentru influențarea soluționării unei cereri privind satisfacerea intereselor oricărei persoane;","l) nerespectarea obligațiilor prevăzute de dispozițiile legale în sarcina acestora, inclusiv a celor cuprinse în Codul deontologic al polițistului de penitenciare și a prevederilor referitoare la incompatibilități, conflicte de interese și interdicții;","m) interzicerea sau împiedicarea exercitării libertăților publice și a drepturilor sindicale ale polițiștilor de penitenciare;","n) atitudinea tolerantă a conducătorilor ierarhici față de comiterea unor abateri disciplinare de către subordonați;","o) efectuarea în timpul programului de lucru a unor activități ce nu au legătură cu îndatoririle de serviciu, de natură a afecta exercitarea în bune condiții a atribuțiilor de serviciu;","p) nerespectarea obligațiilor prevăzute la art. 119."]},
    {id:"l145-141",number:"Art. 141",heading:"Sancțiuni disciplinare",intro:"Sancțiunile disciplinare care pot fi aplicate polițiștilor de penitenciare sunt:",items:["a) mustrarea scrisă;","b) diminuarea drepturilor salariale pentru funcția îndeplinită cu 5-10% pe o perioadă de 1-3 luni;","c) amânarea avansării în grade profesionale sau funcții superioare, pe o perioadă de la 1 la 2 ani;","d) trecerea într-o funcție inferioară până la cel mult nivelul de bază al gradului profesional deținut;","e) revocarea din funcția de conducere;","f) eliberarea din funcție."]}
  ]},
  {id:"cp",title:"Codul penal — Legea nr. 286/2009",scope:"Art. 53–54, 56–60, 71–74, 99–100, 124–127 și 186",url:"https://legislatie.just.ro/Public/DetaliiDocumentAfis/109855",status:"integrat",articles:[
    {id:"cp-53",number:"Art. 53",heading:"Pedepsele principale",intro:"Pedepsele principale sunt:",items:["a) detențiunea pe viață;","b) închisoarea;","c) amenda."]},
    {id:"cp-54",number:"Art. 54",heading:"Pedeapsa accesorie",intro:"Pedeapsa accesorie constă în interzicerea exercitării unor drepturi, din momentul rămânerii definitive a hotărârii de condamnare și până la executarea sau considerarea ca executată a pedepsei privative de libertate.",items:[]},
    {id:"cp-56",number:"Art. 56",heading:"Regimul detențiunii pe viață",intro:"Detențiunea pe viață constă în privarea de libertate pe durată nedeterminată și se execută potrivit legii privind executarea pedepselor.",items:[]},
    {id:"cp-57",number:"Art. 57",heading:"Neaplicarea detențiunii pe viață",intro:"Dacă la data pronunțării hotărârii de condamnare inculpatul a împlinit vârsta de 65 de ani, în locul detențiunii pe viață i se aplică pedeapsa închisorii pe timp de 30 de ani și pedeapsa interzicerii exercitării unor drepturi pe durata ei maximă.",items:[]},
    {id:"cp-58",number:"Art. 58",heading:"Înlocuirea detențiunii pe viață",intro:"În cazul în care cel condamnat la pedeapsa detențiunii pe viață a împlinit vârsta de 65 de ani în timpul executării pedepsei, pedeapsa detențiunii pe viață poate fi înlocuită cu pedeapsa închisorii pe timp de 30 de ani și pedeapsa interzicerii exercitării unor drepturi pe durata ei maximă, dacă a avut o bună conduită pe toată durata executării pedepsei, a îndeplinit integral obligațiile civile stabilite prin hotărârea de condamnare, afară de cazul când dovedește că nu a avut nicio posibilitate să le îndeplinească, și a făcut progrese constante și evidente în vederea reintegrării sociale.",items:[]},
    {id:"cp-59",number:"Art. 59",heading:"Calculul pedepsei în cazul comutării sau înlocuirii detențiunii pe viață",intro:"În cazul comutării sau înlocuirii pedepsei detențiunii pe viață cu pedeapsa închisorii, perioada de detențiune executată se consideră ca parte executată din pedeapsa închisorii.",items:[]},
    {id:"cp-60",number:"Art. 60",heading:"Regimul închisorii",intro:"Închisoarea constă în privarea de libertate pe durată determinată, cuprinsă între 15 zile și 30 de ani, și se execută potrivit legii privind executarea pedepselor.",items:[]},
    {id:"cp-71",number:"Art. 71",heading:"Durata executării",intro:"(1) Durata executării pedepsei privative de libertate se socotește din ziua în care condamnatul a început executarea hotărârii definitive de condamnare.",items:["(2) Ziua în care începe executarea pedepsei și ziua în care încetează se socotesc în durata executării.","(3) Perioada în care condamnatul, în cursul executării pedepsei, se află bolnav în spital intră în durata executării, în afară de cazul în care și-a provocat în mod voit boala, iar această împrejurare se constată în cursul executării pedepsei.","(4) Permisiunile de ieșire din penitenciar, acordate condamnatului conform legii de executare a pedepselor, intră în durata executării pedepsei."]},
    {id:"cp-72",number:"Art. 72",heading:"Computarea duratei măsurilor preventive privative de libertate",intro:"(1) Perioada în care o persoană a fost supusă unei măsuri preventive privative de libertate se scade din durata pedepsei închisorii pronunțate. Scăderea se face și atunci când condamnatul a fost urmărit sau judecat, în același timp ori în mod separat, pentru mai multe infracțiuni concurente, chiar dacă a fost condamnat pentru o altă faptă decât cea care a determinat dispunerea măsurii preventive.",items:["(2) Perioada în care o persoană a fost supusă unei măsuri preventive privative de libertate se scade și în caz de condamnare la pedeapsa amenzii, prin înlăturarea în tot sau în parte a zilelor-amendă.","(3) În cazul amenzii care însoțește pedeapsa închisorii, perioada în care o persoană a fost supusă unei măsuri preventive privative de libertate se scade din durata pedepsei închisorii."]},
    {id:"cp-73",number:"Art. 73",heading:"Computarea pedepselor și măsurilor preventive executate în afara țării",intro:"(1) În cazul infracțiunilor săvârșite în condițiile art. 8, art. 9, art. 10 sau art. 11, partea din pedeapsă, precum și durata măsurilor preventive privative de libertate executate în afara teritoriului țării se scad din durata pedepsei aplicate pentru aceeași infracțiune în România.",items:["(2) Dispozițiile alin. (1) se aplică în mod corespunzător și în cazul în care pedeapsa executată în afara țării este amenda."]},
    {id:"cp-74",number:"Art. 74",heading:"Criteriile generale de individualizare a pedepsei",intro:"(1) Stabilirea duratei ori a cuantumului pedepsei se face în raport cu gravitatea infracțiunii săvârșite și cu periculozitatea infractorului, care se evaluează după următoarele criterii:",items:["a) împrejurările și modul de comitere a infracțiunii, precum și mijloacele folosite;","b) starea de pericol creată pentru valoarea ocrotită;","c) natura și gravitatea rezultatului produs ori a altor consecințe ale infracțiunii;","d) motivul săvârșirii infracțiunii și scopul urmărit;","e) natura și frecvența infracțiunilor care constituie antecedente penale ale infractorului;","f) conduita după săvârșirea infracțiunii și în cursul procesului penal;","g) nivelul de educație, vârsta, starea de sănătate, situația familială și socială."],subsections:[{intro:"(2) Când pentru infracțiunea săvârșită legea prevede pedepse alternative, se ține seama de criteriile prevăzute în alin. (1) și pentru alegerea uneia dintre acestea.",items:[]}]},
    {id:"cp-99",number:"Art. 99",heading:"Condițiile liberării condiționate în cazul detențiunii pe viață",intro:"(1) Liberarea condiționată în cazul detențiunii pe viață poate fi dispusă, dacă:",items:["a) cel condamnat a executat efectiv 20 de ani de detențiune;","b) cel condamnat a avut o bună conduită pe toată durata executării pedepsei;","c) cel condamnat a îndeplinit integral obligațiile civile stabilite prin hotărârea de condamnare, afară de cazul când dovedește că nu a avut nicio posibilitate să le îndeplinească;","d) instanța are convingerea că persoana condamnată s-a îndreptat și se poate reintegra în societate."],subsections:[{intro:"(2) Este obligatorie prezentarea motivelor de fapt ce au determinat acordarea liberării condiționate și atenționarea condamnatului asupra conduitei sale viitoare și a consecințelor la care se expune, dacă va mai comite infracțiuni sau nu va respecta măsurile de supraveghere ori dacă nu va executa obligațiile ce îi revin pe durata termenului de supraveghere.",items:[]},{intro:"(3) De la data liberării condiționate, condamnatul este supus unui termen de supraveghere de 10 ani.",items:[]}]},
    {id:"cp-100",number:"Art. 100",heading:"Condițiile liberării condiționate în cazul pedepsei închisorii",intro:"(1) Liberarea condiționată în cazul închisorii poate fi dispusă, dacă:",items:["a) cel condamnat a executat cel puțin două treimi din durata pedepsei, în cazul închisorii care nu depășește 10 ani, sau cel puțin trei pătrimi din durata pedepsei, dar nu mai mult de 20 de ani, în cazul închisorii mai mari de 10 ani;","b) cel condamnat se află în executarea pedepsei în regim semideschis sau deschis;","c) cel condamnat a îndeplinit integral obligațiile civile stabilite prin hotărârea de condamnare, afară de cazul când dovedește că nu a avut nicio posibilitate să le îndeplinească;","d) instanța are convingerea că persoana condamnată s-a îndreptat și se poate reintegra în societate."],subsections:[{intro:"(2) În cazul condamnatului care a împlinit vârsta de 60 de ani, se poate dispune liberarea condiționată, după executarea efectivă a jumătate din durata pedepsei, în cazul închisorii ce nu depășește 10 ani, sau a cel puțin două treimi din durata pedepsei, în cazul închisorii mai mari de 10 ani, dacă sunt îndeplinite condițiile prevăzute în alin. (1) lit. b)-d).",items:[]},{intro:"(3) În calculul fracțiunilor de pedeapsă prevăzute în alin. (1) se ține seama de partea din durata pedepsei ce poate fi considerată, potrivit legii, ca executată pe baza muncii prestate. În acest caz, liberarea condiționată nu poate fi dispusă înainte de executarea efectivă a cel puțin jumătate din durata pedepsei închisorii, când aceasta nu depășește 10 ani, și a cel puțin două treimi, când pedeapsa este mai mare de 10 ani.",items:[]},{intro:"(4) În calculul fracțiunilor de pedeapsă prevăzute în alin. (2) se ține seama de partea din durata pedepsei ce poate fi considerată, potrivit legii, ca executată pe baza muncii prestate. În acest caz, liberarea condiționată nu poate fi dispusă înainte de executarea efectivă a cel puțin o treime din durata pedepsei închisorii, când aceasta nu depășește 10 ani, și a cel puțin jumătate, când pedeapsa este mai mare de 10 ani.",items:[]},{intro:"(5) Este obligatorie prezentarea motivelor de fapt ce au determinat acordarea liberării condiționate și atenționarea condamnatului asupra conduitei sale viitoare și a consecințelor la care se expune, dacă va mai comite infracțiuni sau nu va respecta măsurile de supraveghere ori nu va executa obligațiile ce îi revin pe durata termenului de supraveghere.",items:[]},{intro:"(6) Intervalul cuprins între data liberării condiționate și data împlinirii duratei pedepsei constituie termen de supraveghere pentru condamnat.",items:[]}]},
    {id:"cp-124",number:"Art. 124",heading:"Internarea într-un centru educativ",intro:"(1) Măsura educativă a internării într-un centru educativ constă în internarea minorului într-o instituție specializată în recuperarea minorilor, unde va urma un program de pregătire școlară și formare profesională potrivit aptitudinilor sale, precum și programe de reintegrare socială.",items:["(2) Internarea se dispune pe o perioadă cuprinsă între unu și 3 ani.","(3) Dacă în perioada internării minorul săvârșește o nouă infracțiune sau este judecat pentru o infracțiune concurentă săvârșită anterior, instanța poate menține măsura internării într-un centru educativ, prelungind durata acesteia, fără a depăși maximul prevăzut de lege, sau o poate înlocui cu măsura internării într-un centru de detenție."],subsections:[{intro:"(4) În cazul în care pe durata internării minorul a dovedit interes constant pentru însușirea cunoștințelor școlare și profesionale și a făcut progrese evidente în vederea reintegrării sociale, după executarea a cel puțin jumătate din durata internării, instanța poate dispune:",items:["a) înlocuirea internării cu măsura educativă a asistării zilnice pe o perioadă egală cu durata internării neexecutate, dar nu mai mult de 6 luni, dacă persoana internată nu a împlinit vârsta de 18 ani;","b) liberarea din centrul educativ, dacă persoana internată a împlinit vârsta de 18 ani."]},{intro:"(5) Odată cu înlocuirea sau liberarea instanța impune respectarea uneia sau mai multora dintre obligațiile prevăzute în art. 121 până la împlinirea duratei măsurii internării.",items:[]},{intro:"(6) Dacă minorul nu respectă, cu rea-credință, condițiile de executare a măsurii asistării zilnice sau obligațiile impuse, instanța revine asupra înlocuirii sau liberării și dispune executarea restului rămas neexecutat din durata măsurii internării într-un centru educativ.",items:[]},{intro:"(7) În cazul săvârșirii, până la împlinirea duratei internării, a unei noi infracțiuni de către o persoană care nu a împlinit vârsta de 18 ani și față de care s-a dispus înlocuirea măsurii internării într-un centru educativ cu măsura asistării zilnice, instanța revine asupra înlocuirii și dispune:",items:["a) executarea restului rămas din durata măsurii internării inițiale, cu posibilitatea prelungirii duratei acesteia până la maximul prevăzut de lege;","b) internarea într-un centru de detenție."]}]},
    {id:"cp-125",number:"Art. 125",heading:"Internarea într-un centru de detenție",intro:"(1) Măsura educativă a internării într-un centru de detenție constă în internarea minorului într-o instituție specializată în recuperarea minorilor, cu regim de pază și supraveghere, unde va urma programe intensive de reintegrare socială, precum și programe de pregătire școlară și formare profesională potrivit aptitudinilor sale.",items:["(2) Internarea se dispune pe o perioadă cuprinsă între 2 și 5 ani, afară de cazul în care pedeapsa prevăzută de lege pentru infracțiunea săvârșită este închisoarea de 20 de ani sau mai mare ori detențiunea pe viață, când internarea se ia pe o perioadă cuprinsă între 5 și 15 ani.","(3) Dacă în perioada internării minorul săvârșește o nouă infracțiune sau este judecat pentru o infracțiune concurentă săvârșită anterior, instanța prelungește măsura internării, fără a depăși maximul prevăzut în alin. (2), determinat în raport cu pedeapsa cea mai grea dintre cele prevăzute de lege pentru infracțiunile săvârșite. Din durata măsurii educative se scade perioada executată până la data hotărârii."],subsections:[{intro:"(4) În cazul în care pe durata internării minorul a dovedit interes constant pentru însușirea cunoștințelor școlare și profesionale și a făcut progrese evidente în vederea reintegrării sociale, după executarea a cel puțin jumătate din durata internării, instanța poate dispune:",items:["a) înlocuirea internării cu măsura educativă a asistării zilnice pe o perioadă egală cu durata internării neexecutate, dar nu mai mult de 6 luni, dacă persoana internată nu a împlinit vârsta de 18 ani;","b) liberarea din centrul de detenție, dacă persoana internată a împlinit vârsta de 18 ani."]},{intro:"(5) Odată cu înlocuirea sau liberarea, instanța impune respectarea uneia sau mai multora dintre obligațiile prevăzute în art. 121, până la împlinirea duratei măsurii internării.",items:[]},{intro:"(6) Dacă minorul nu respectă, cu rea-credință, condițiile de executare a măsurii asistării zilnice sau obligațiile impuse, instanța revine asupra înlocuirii sau liberării și dispune executarea restului rămas neexecutat din durata măsurii internării într-un centru de detenție.",items:[]},{intro:"(7) În cazul săvârșirii, până la împlinirea duratei internării, a unei noi infracțiuni de către o persoană care nu a împlinit vârsta de 18 ani și față de care s-a dispus înlocuirea măsurii internării într-un centru de detenție cu măsura asistării zilnice, instanța revine asupra înlocuirii și dispune:",items:["a) executarea restului rămas din durata măsurii internării într-un centru de detenție;","b) prelungirea duratei acestei internări în condițiile prevăzute în alin. (3)."]}]},
    {id:"cp-126",number:"Art. 126",heading:"Schimbarea regimului de executare",intro:"Dacă în cursul executării unei măsuri educative privative de libertate persoana internată, care a împlinit vârsta de 18 ani, are un comportament prin care influențează negativ sau împiedică procesul de recuperare și reintegrare a celorlalte persoane internate, instanța poate dispune continuarea executării măsurii educative într-un penitenciar.",items:[]},
    {id:"cp-127",number:"Art. 127",heading:"Calculul duratei măsurilor educative",intro:"În cazul măsurilor educative privative de libertate, dispozițiile art. 71-73 se aplică în mod corespunzător.",items:[]},
    {id:"cp-186",number:"Art. 186",heading:"Calculul timpului",intro:"(1) La calcularea timpului ziua se socotește de 24 de ore, săptămâna de 7 zile, iar anul de 12 luni. Luna și anul se socotesc împlinite cu o zi înainte de ziua corespunzătoare datei de la care au început să curgă.",items:["(2) Dacă limita de pedeapsă este exprimată într-un termen pe luni care nu este divizibil cu fracția de majorare sau reducere ce ar urma să se aplice, fracția se va aplica asupra termenului transformat în zile, după care durata obținută se transformă în luni. În acest caz, luna se socotește de 30 de zile și se iau în calcul doar zilele întregi rezultate din aplicarea fracției.","(3) În cazul limitelor de pedeapsă exprimate în ani se aplică în mod corespunzător dispozițiile alin. (2), transformarea făcându-se între ani și luni."]}
  ]},
  {"id":"cpp","title":"Codul de procedură penală — Legea nr. 135/2010","scope":"Art. 208, 238–239, 241–242, 269, 362, 399, 550–558, 581¹, 582–588, 595–596 și 598","url":"https://legislatie.just.ro/Public/DetaliiDocument/265008","status":"integrat","articles":[{"heading":"Verificarea măsurilor preventive în cursul judecății","id":"cpp-208","intro":"(1) Judecătorul de cameră preliminară înaintează dosarul instanței de judecată cu cel puțin 5 zile înainte de expirarea măsurii preventive.","items":["(2) Instanța de judecată verifică din oficiu dacă subzistă temeiurile care au determinat luarea, prelungirea sau menținerea măsurii preventive, înainte de expirarea duratei acesteia, cu citarea inculpatului.","(3) Dispozițiile art. 207 alin. (3)-(5) se aplică în mod corespunzător.","(4) În tot cursul judecății, până la pronunțarea hotărârii, instanța, din oficiu, prin încheiere, verifică periodic, dar nu mai târziu de 60 de zile, dacă subzistă temeiurile care au determinat menținerea măsurii arestării preventive și a măsurii arestului la domiciliu dispuse față de inculpat sau dacă au apărut temeiuri noi, care să justifice menținerea acestor măsuri. Dispozițiile art. 207 alin. (3)-(5) se aplică în mod corespunzător.","(5) În tot cursul judecății, până la pronunțarea hotărârii, instanța verifică, prin încheiere, din oficiu, periodic, dar nu mai târziu de 60 de zile, dacă subzistă temeiurile care au determinat luarea măsurii controlului judiciar ori a controlului judiciar pe cauțiune sau dacă au apărut temeiuri noi, care să justifice menținerea acestei măsuri. Dispozițiile art. 207 alin. (3-(5) se aplică în mod corespunzător."],"number":"Art. 208"},{"heading":"Arestarea preventivă a inculpatului în procedura de cameră preliminară și în cursul judecății","id":"cpp-238","intro":"(1) Arestarea preventivă a inculpatului poate fi dispusă în procedura de cameră preliminară și în cursul judecății, de către judecătorul de cameră preliminară sau de către instanța de judecată în fața căreia se află cauza, din oficiu ori la propunerea motivată a procurorului, pentru o perioadă de cel mult 30 de zile, pentru aceleași temeiuri și în aceleași condiții ca și arestarea preventivă dispusă de către judecătorul de drepturi și libertăți în cursul urmăririi penale. Dispozițiile art. 225-232 se aplică în mod corespunzător.","items":["(2) În cursul judecății, măsura prevăzută la alin. (1) se poate dispune de către instanța de judecată în compunerea prevăzută de lege. În acest caz, mandatul de arestare preventivă este emis de către președintele completului.","(3) Față de inculpatul care a mai fost anterior arestat preventiv în aceeași cauză, în cursul urmăririi penale, al procedurii de cameră preliminară sau al judecății, se poate dispune din nou această măsură numai dacă au intervenit temeiuri noi care fac necesară privarea sa de libertate."],"number":"Art. 238"},{"heading":"Durata maximă a arestării preventive a inculpatului în cursul judecății în primă instanță","id":"cpp-239","intro":"(1) În cursul judecății în primă instanță, durata totală a arestării preventive a inculpatului nu poate depăși un termen rezonabil și nu poate fi mai mare de jumătatea maximului special prevăzut de lege pentru infracțiunea care face obiectul sesizării instanței de judecată. În toate cazurile, durata arestării preventive în primă instanță nu poate depăși 5 ani.","items":["(2) Termenele prevăzute la alin. (1) curg de la data sesizării instanței de judecată, în cazul în care inculpatul se află în stare de arest preventiv, și, respectiv, de la data punerii în executare a măsurii, când față de acesta s-a dispus arestarea preventivă în procedura de cameră preliminară sau în cursul judecății sau în lipsă.","(3) La expirarea termenelor prevăzute la alin. (1), instanța de judecată poate dispune luarea unei alte măsuri preventive, în condițiile legii."],"number":"Art. 239"},{"heading":"Încetarea de drept a măsurilor preventive","id":"cpp-241","intro":"(1) Măsurile preventive încetează de drept:a) la expirarea termenelor prevăzute de lege sau stabilite de organele judiciare ori, în cursul urmăririi penale sau în cursul judecății în primă instanță, la împlinirea duratei maxime prevăzute de lege; ... b) în cazurile în care procurorul dispune o soluție de netrimitere în judecată ori instanța de judecată pronunță o hotărâre de achitare, de încetare a procesului penal, de renunțare la aplicarea pedepsei sau de amânare a aplicării pedepsei ori o pedeapsă cu amendă, care nu însoțește pedeapsa închisorii, chiar nedefinitivă; ... c) la data rămânerii definitive a hotărârii prin care s-a dispus condamnarea inculpatului; ... d) în alte cazuri anume prevăzute de lege. ... e) abrogată; ... f) abrogată; ... g) abrogată; ...","items":["(1^1) Arestarea preventivă și arestul la domiciliu încetează de drept și în următoarele situații:a) la pronunțarea în primă instanță a unei hotărâri de condamnare cu suspendarea executării pedepsei sub supraveghere sau la o pedeapsă cu închisoare cel mult egală cu durata reținerii, arestului la domiciliu și arestării preventive ori, după caz, a unei hotărâri prin care s-a aplicat o măsură educativă neprivativă de libertate; ... b) în apel, dacă durata măsurii a atins durata pedepsei pronunțate în hotărârea de condamnare. ...","(2) Organul judiciar care a dispus această măsură sau, după caz, procurorul, judecătorul de drepturi și libertăți, judecătorul de cameră preliminară ori instanța de judecată în fața căreia se află cauza constată, prin ordonanță sau încheiere, din oficiu, la cerere sau la sesizarea administrației locului de deținere, încetarea de drept a măsurii preventive, dispunând, în cazul celui reținut sau arestat preventiv, punerea de îndată în libertate, dacă nu este reținut ori arestat în altă cauză.","(3) Judecătorul de drepturi și libertăți, judecătorul de cameră preliminară sau instanța de judecată se pronunță, prin încheiere motivată, asupra încetării de drept a măsurii preventive chiar și în lipsa inculpatului. Asistența juridică a inculpatului și participarea procurorului sunt obligatorii.","(4) Persoanei față de care s-a dispus măsura preventivă, precum și tuturor instituțiilor cu atribuții în executarea măsurii li se comunică de îndată câte o copie de pe ordonanța sau încheierea prin care organul judiciar constată încetarea de drept a măsurii preventive."],"number":"Art. 241"},{"heading":"Revocarea măsurilor preventive și înlocuirea unei măsuri preventive cu o altă măsură preventivă","id":"cpp-242","intro":"(1) Măsura preventivă se revocă, din oficiu sau la cerere, în cazul în care au încetat temeiurile care au determinat-o ori au apărut împrejurări noi din care rezultă nelegalitatea măsurii, dispunându-se, în cazul reținerii și arestării preventive, punerea în libertate a suspectului ori a inculpatului, dacă nu este arestat în altă cauză.","items":["(2) Măsura preventivă se înlocuiește, din oficiu sau la cerere, cu o măsură preventivă mai ușoară, dacă sunt îndeplinite condițiile prevăzute de lege pentru luarea acesteia și, în urma evaluării împrejurărilor concrete ale cauzei și a conduitei procesuale a inculpatului, se apreciază că măsura preventivă mai ușoară este suficientă pentru realizarea scopului prevăzut la art. 202 alin. (1).","(3) Măsura preventivă se înlocuiește, din oficiu sau la cerere, cu o măsură preventivă mai grea, dacă sunt îndeplinite condițiile prevăzute de lege pentru luarea acesteia și, în urma evaluării împrejurărilor concrete ale cauzei și a conduitei procesuale a inculpatului, se apreciază că măsura preventivă mai grea este necesară pentru realizarea scopului prevăzut la art. 202 alin. (1).","(4) În cazul în care măsura preventivă a fost luată în cursul urmăririi penale de către procuror sau de către judecătorul de drepturi și libertăți, organul de cercetare penală are obligația să îl informeze de îndată, în scris, pe procuror despre orice împrejurare care ar putea conduce la revocarea sau înlocuirea măsurii preventive. Dacă apreciază că informațiile comunicate justifică revocarea sau înlocuirea măsurii preventive, procurorul dispune aceasta sau, după caz, sesizează judecătorul de drepturi și libertăți care a luat măsura, în termen de 24 de ore de la primirea informării. Procurorul este obligat să sesizeze și din oficiu judecătorul de drepturi și libertăți, când constată el însuși existența vreunei împrejurări care justifică revocarea sau înlocuirea măsurii preventive luate de acesta.","(4^1) În cursul urmăririi penale, revocarea măsurilor preventive ale controlului judiciar și controlului judiciar pe cauțiune, precum și înlocuirea acestor măsuri între ele se dispun de procuror, chiar dacă măsura a fost luată de către judecătorul de drepturi și libertăți. La înlocuirea măsurii preventive a controlului judiciar cu măsura controlului judiciar pe cauțiune, dispozițiile art. 216 alin. (1) și (3) și art. 217 se aplică în mod corespunzător.","(4^2) Împotriva ordonanței procurorului, dispuse potrivit alin. (4^1), se poate formula plângere, în condițiile art. 213.","(5) Cererea de revocare sau înlocuire a măsurii preventive formulată de inculpat se adresează, în scris, procurorului, judecătorului de drepturi și libertăți, judecătorului de cameră preliminară sau instanței de judecată, după caz.","(6) În cursul urmăririi penale, procurorul înaintează judecătorului de drepturi și libertăți dosarul cauzei sau copie de pe acesta certificată de grefa parchetului, în termen de 24 de ore de la solicitarea acestuia de către judecător.","(7) În vederea soluționării cererii, judecătorul de drepturi și libertăți, judecătorul de cameră preliminară sau instanța de judecată fixează data de soluționare a acesteia și dispune citarea inculpatului.","(8) Când inculpatul este prezent, soluționarea cererii se face numai după ascultarea acestuia asupra tuturor motivelor pe care se întemeiază cererea, în prezența unui avocat ales sau numit din oficiu. Cererea se soluționează și în lipsa inculpatului, atunci când acesta nu se prezintă, deși a fost legal citat sau când, din cauza stării de sănătate, din cauză de forță majoră ori stare de necesitate, nu poate fi adus, dar numai în prezența avocatului, ales sau numit din oficiu, căruia i se dă cuvântul pentru a pune concluzii.","(9) Participarea procurorului este obligatorie.","(10) Dacă cererea are ca obiect înlocuirea măsurii arestării preventive sau a măsurii arestului la domiciliu cu măsura controlului judiciar pe cauțiune, dacă găsește cererea întemeiată, judecătorul de drepturi și libertăți, judecătorul de cameră preliminară sau instanța de judecată, prin încheiere, dată în camera de consiliu, admite în principiu cererea și stabilește valoarea cauțiunii, acordând inculpatului termen pentru depunerea ei.","(11) Dacă se depune cauțiunea în termenul fixat, judecătorul de drepturi și libertăți, judecătorul de cameră preliminară sau instanța de judecată, prin încheiere dată în camera de consiliu, admite cererea de înlocuire a măsurii preventive cu măsura controlului judiciar pe cauțiune, stabilește obligațiile ce vor reveni inculpatului pe durata măsurii și dispune punerea de îndată în libertate a inculpatului, dacă nu este arestat în altă cauză.","(12) Dacă nu se depune cauțiunea în termenul fixat, judecătorul de drepturi și libertăți, judecătorul de cameră preliminară sau instanța de judecată, prin încheiere dată în camera de consiliu, în lipsa inculpatului și a procurorului, respinge ca neîntemeiată cererea formulată de inculpat.","(13) Termenul prevăzut la alin. (10) curge de la data rămânerii definitive a încheierii prin care se stabilește valoarea cauțiunii."],"number":"Art. 242"},{"heading":"Calculul termenelor procedurale","id":"cpp-269","intro":"(1) La calcularea termenelor procedurale se pornește de la ora, ziua, luna sau anul prevăzut în actul care a provocat curgerea termenului, în afară de cazul când legea dispune altfel.","items":["(2) La calcularea termenelor pe ore sau pe zile nu se socotește ora sau ziua de la care începe să curgă termenul, nici ora sau ziua în care acesta se împlinește.","(3) Termenele socotite pe luni sau pe ani expiră, după caz, la sfârșitul zilei corespunzătoare a ultimei luni ori la sfârșitul zilei și lunii corespunzătoare din ultimul an. Dacă această zi cade într-o lună care nu are zi corespunzătoare, termenul expiră în ultima zi a acelei luni.","(4) Când ultima zi a unui termen cade într-o zi nelucrătoare, termenul expiră la sfârșitul primei zile lucrătoare care urmează."],"number":"Art. 269"},{"heading":"Măsurile preventive în cursul judecății","id":"cpp-362","intro":"(1) În tot cursul judecății, până la pronunțarea hotărârii, instanța se pronunță, la cerere sau din oficiu, cu privire la luarea, înlocuirea, revocarea sau încetarea de drept a măsurilor preventive.","items":["(2) În cauzele în care față de inculpat s-a dispus o măsură preventivă, instanța este datoare să verifice, în tot cursul judecății, până la pronunțarea hotărârii, în ședință publică, legalitatea și temeinicia măsurii preventive, procedând potrivit dispozițiilor art. 208."],"number":"Art. 362"},{"heading":"Dispozițiile cu privire la măsurile preventive","id":"cpp-399","intro":"(1) Instanța are obligația ca, prin hotărâre, să se pronunțe asupra menținerii, revocării, înlocuirii ori încetării de drept a măsurii preventive dispuse pe parcursul procesului penal cu privire la inculpat.","items":["(2) În caz de renunțare la aplicarea pedepsei, de amânare a aplicării pedepsei, de achitare sau de încetare a procesului penal, instanța dispune punerea de îndată în libertate a inculpatului arestat preventiv.","(3) De asemenea, instanța dispune punerea de îndată în libertate a inculpatului arestat preventiv atunci când pronunță:a) o pedeapsă cu închisoare cel mult egală cu durata reținerii, arestului la domiciliu și arestării preventive; ... b) o pedeapsă cu închisoare, cu suspendarea executării sub supraveghere; ... c) o pedeapsă cu amendă, care nu însoțește pedeapsa închisorii; ... d) o măsură educativă neprivativă de libertate. ...","(4) Hotărârea pronunțată în condițiile alin. (1)-(3) cu privire la măsurile preventive este executorie.","(5) Când, potrivit dispozițiilor prevăzute la alin. (1)-(3), inculpatul este pus în libertate, instanța comunică aceasta administrației locului de deținere.","(6) Inculpatul condamnat de prima instanță și aflat în stare de arest preventiv este liberat de îndată ce durata reținerii și cea a arestării devin egale cu durata pedepsei pronunțate, deși hotărârea nu este definitivă. Liberarea se dispune de administrația locului de deținere, căreia i se comunică, îndată după pronunțarea hotărârii, o copie de pe dispozitiv sau extras.","(7) În caz de renunțare la aplicarea pedepsei, de amânare a aplicării pedepsei, de achitare sau de încetare a procesului penal, dacă în cursul urmăririi penale sau al judecății față de inculpat s-a luat măsura preventivă a controlului judiciar pe cauțiune, instanța va dispune restituirea sumei depuse drept cauțiune, dacă nu s-a dispus plata din aceasta a despăgubirilor acordate pentru repararea pagubelor și dacă nu s-a dispus plata din cauțiune prevăzută la art. 217 alin. (7).","(8) Instanța dispune confiscarea cauțiunii dacă măsura controlului judiciar pe cauțiune a fost înlocuită cu măsura arestului la domiciliu sau a arestării preventive, pentru motivele arătate la art. 217 alin. (9), și nu s-a dispus plata din cauțiune a sumelor prevăzute la art. 217.","(9) Durata măsurii arestului la domiciliu se deduce din pedeapsa aplicată prin echivalarea unei zile de arest la domiciliu cu o zi din pedeapsă.","(10) După pronunțarea hotărârii, până la sesizarea instanței de apel, instanța poate dispune, la cerere sau din oficiu, luarea, revocarea, înlocuirea sau menținerea unei măsuri preventive cu privire la inculpatul condamnat, în condițiile legii."],"number":"Art. 399"},{"heading":"Hotărârile executorii","id":"cpp-550","intro":"(1) Hotărârile instanțelor penale devin executorii la data când au rămas definitive.","items":["(2) Hotărârile nedefinitive sunt executorii atunci când legea dispune aceasta."],"number":"Art. 550"},{"heading":"Rămânerea definitivă a hotărârii primei instanțe","id":"cpp-551","intro":"Hotărârile primei instanțe rămân definitive:","items":[],"number":"Art. 551"},{"heading":"Rămânerea definitivă a hotărârii instanței de apel și a hotărârii pronunțate în calea de atac a contestației","id":"cpp-552","intro":"(1) Hotărârea instanței de apel rămâne definitivă la data pronunțării acesteia, atunci când apelul a fost admis și procesul a luat sfârșit în fața instanței de apel.","items":["(2) Hotărârea pronunțată în calea de atac a contestației rămâne definitivă la data pronunțării acesteia, atunci când contestația a fost admisă și procesul a luat sfârșit în fața instanței care o judecă."],"number":"Art. 552"},{"heading":"Instanța de executare","id":"cpp-553","intro":"(1) Hotărârea instanței penale, rămasă definitivă la prima instanță de judecată sau la instanța ierarhic superioară ori la instanța de apel, se pune în executare de către prima instanță de judecată.","items":["(2) Hotărârile pronunțate în primă instanță de către Înalta Curte de Casație și Justiție se pun în executare, după caz, de Tribunalul București sau de tribunalul militar.","(3) Când hotărârea rămâne definitivă în fața instanței de apel sau în fața instanței ierarhic superioare, aceasta trimite instanței de executare un extras din acea hotărâre, cu datele necesare punerii în executare, în ziua pronunțării hotărârii de către instanța de apel sau, după caz, de către instanța ierarhic superioară.","(4) Dispozițiile alin. (1)-(3) sunt aplicabile și în cazul hotărârilor nedefinitive, dar executorii, cu excepția celor privind măsurile de siguranță, măsurile asigurătorii și măsurile preventive, care se pun în executare, după caz, de judecătorul de drepturi și libertăți, judecătorul de cameră preliminară sau de instanța care le-a dispus.","(5) Când hotărârea instanței de apel a fost modificată prin hotărârea Înaltei Curți de Casație și Justiție, pronunțată în recurs în casație, Înalta Curte de Casație și Justiție procedează potrivit alin. (3).","(6) În cazul pedepselor și măsurilor neprivative de libertate, judecătorul delegat cu executarea din cadrul instanței de executare poate delega unele atribuții judecătorului delegat cu executarea de la instanța corespunzătoare în grad instanței de executare în circumscripția căreia locuiește persoana aflată în executare."],"number":"Art. 553"},{"heading":"Judecătorul delegat cu executarea","id":"cpp-554","intro":"(1) Instanța de executare deleagă unul sau mai mulți dintre judecătorii săi pentru efectuarea punerii în executare.","items":["(2) Dacă la punerea în executare a hotărârii sau în cursul executării se ivește vreo nelămurire sau împiedicare la executare, judecătorul delegat cu executarea poate sesiza instanța de executare, care va proceda potrivit dispozițiilor art. 597 și 598."],"number":"Art. 554"},{"heading":"Punerea în executare a pedepsei închisorii sau a detențiunii pe viață și a pedepsei accesorii","id":"cpp-555","intro":"(1) Pedeapsa închisorii și pedeapsa detențiunii pe viață se pun în executare prin emiterea mandatului de executare. Mandatul de executare se emite de judecătorul delegat cu executarea în ziua rămânerii definitive a hotărârii la instanța de fond sau, după caz, în ziua primirii extrasului prevăzut la art. 553 alin. (3), se întocmește în 3 exemplare și cuprinde: denumirea instanței de executare, data emiterii, datele privitoare la persoana condamnatului, numărul și data hotărârii care se execută și denumirea instanței care a pronunțat-o, pedeapsa pronunțată și textul de lege aplicat, pedeapsa accesorie aplicată, timpul reținerii și arestării preventive ori al arestului la domiciliu, care s-a dedus din durata pedepsei, mențiunea dacă cel condamnat este recidivist, precum și, după caz, mențiunea prevăzută la art. 404 alin. (6), ordinul de arestare și de deținere, semnătura judecătorului delegat, precum și ștampila instanței de executare.","items":["(2) În cazul în care cel condamnat se află în stare de libertate, odată cu emiterea mandatului de executare a pedepsei închisorii sau a pedepsei detențiunii pe viață, judecătorul delegat cu executarea emite și un ordin prin care interzice condamnatului să părăsească țara. Ordinul se întocmește în 3 exemplare și cuprinde: denumirea instanței de executare, data emiterii, datele privitoare la persoana condamnatului, pedeapsa pronunțată împotriva acestuia, numărul și data hotărârii de condamnare, denumirea instanței care a pronunțat-o, numărul mandatului de executare a pedepsei emis pe numele condamnatului, dispoziția de interzicere a părăsirii țării, semnătura judecătorului delegat, precum și ștampila instanței de executare."],"number":"Art. 555"},{"heading":"Trimiterea spre executare a mandatului","id":"cpp-556","intro":"(1) Pentru ducerea la îndeplinire a mandatului de executare se trimit două exemplare organului de poliție de la domiciliul sau reședința condamnatului, iar în cazul în care acesta nu are domiciliul sau reședința în România, organului de poliție în raza teritorială a căruia se află instanța de executare, când condamnatul este liber, sau, după caz, când condamnatul este arestat, comandantului la locul de deținere.","items":["(1^1) În situația în care mandatul de executare conține erori materiale, însă permite identificarea persoanei în vederea punerii în executare, în raport cu datele de identificare ale persoanei existente în evidențele organelor de poliție și hotărârea instanței de judecată, organul de poliție execută hotărârea, solicitând, în același timp, instanței de judecată îndreptarea erorilor materiale sesizate.","(2) Pentru aducerea la îndeplinire a ordinului de interzicere a părăsirii țării se trimite de îndată câte un exemplar organului competent să elibereze pașaportul și Inspectoratului General al Poliției de Frontieră.","(2^1) Mandatul de executare sau ordinul de interzicere a părăsirii țării poate fi transmis organelor competente și prin fax, poștă electronică sau prin orice mijloc în măsură să producă un document scris în condiții care să permită autorităților destinatare să îi stabilească autenticitatea.","(3) În cazul în care cel condamnat se află în stare de libertate, organele de executare prevăzute la alin. (1) și (2) au obligația de a lua măsurile prevăzute de lege în vederea punerii în executare a mandatului de executare a pedepsei și a ordinului de interzicere a părăsirii țării, în ziua primirii acestora."],"number":"Art. 556"},{"heading":"Executarea mandatului de executare a pedepsei și a ordinului de interzicere a părăsirii țării. Acordul instanței de părăsire a țării","id":"cpp-557","intro":"(1) Pe baza mandatului de executare, organul de poliție procedează la arestarea condamnatului. Celui arestat i se înmânează un exemplar al mandatului și este dus la locul de deținere cel mai apropiat, unde organul de poliție predă celălalt exemplar al mandatului de executare. În termen de cel mult 10 zile de la arestare, persoanei private de libertate i se comunică o copie de pe hotărâre.","items":["(1^1) Abrogat.","(1^2) Odată cu înmânarea mandatului de executare, persoanei condamnate i se aduce la cunoștință, sub semnătură, în scris, dreptul prevăzut la art. 466 alin. (1), iar în cazul în care persoana nu poate ori refuză să semneze, se va încheia un proces-verbal.","(2) În vederea punerii în executare a mandatului emis în executarea unei hotărâri definitive de condamnare, organul de poliție poate pătrunde în domiciliul sau reședința unei persoane fără învoirea acesteia, precum și în sediul unei persoane juridice fără învoirea reprezentantului legal al acesteia.","(3) Dispozițiile art. 229 privind luarea măsurilor de ocrotire sunt aplicabile în mod corespunzător, obligația de încunoștințare revenind organului de poliție.","(4) Dacă persoana împotriva căreia s-a emis mandatul nu este găsită, organul de poliție constată aceasta printr-un proces-verbal și ia măsuri pentru darea în urmărire, precum și pentru darea în consemn la punctele de trecere a frontierei. Un exemplar de pe procesul-verbal împreună cu un exemplar al mandatului de executare se trimit instanței care a emis mandatul.","(5) Dacă persoana condamnată refuză să se supună mandatului sau încearcă să fugă, va fi constrânsă la aceasta.","(6) Când condamnatul se află în stare de deținere, un exemplar al mandatului de executare i se înmânează de către comandantul locului de deținere.","(7) Comandantul locului de deținere consemnează într-un proces-verbal data de la care condamnatul a început executarea pedepsei.","(8) O copie de pe procesul-verbal se trimite de îndată instanței de executare.","(9) Pe baza ordinului de interzicere a părăsirii țării, organele în drept refuză celui condamnat eliberarea pașaportului sau, după caz, procedează la ridicarea acestuia și iau măsuri pentru darea condamnatului în consemn la punctele de trecere a frontierei.","(10) Pe durata termenului de supraveghere, persoana supravegheată poate solicita motivat instanței de executare să încuviințeze părăsirea teritoriului României potrivit art. 85 alin. (2) lit. i) sau art. 93 alin. (2) lit. d) din Codul penal. Instanța de executare soluționează cererea în camera de consiliu, după ascultarea persoanei supravegheate și a consilierului de probațiune, prin încheiere definitivă. În cazul în care admite cererea, instanța stabilește perioada pentru care persoana supravegheată poate părăsi teritoriul României."],"number":"Art. 557"},{"heading":"Încunoștințarea despre arestare în vederea executării mandatului","id":"cpp-558","intro":"(1) Imediat după arestarea în vederea executării mandatului, condamnatul are dreptul de a încunoștința personal sau de a solicita administrației locului de deținere să încunoștințeze un membru al familiei sale ori o altă persoană desemnată de acesta despre arestare și despre locul unde este deținut.","items":["(2) Dacă persoana condamnată nu este cetățean român, aceasta are și dreptul de a încunoștința sau de a solicita încunoștințarea misiunii diplomatice ori oficiului consular al statului al cărui cetățean este sau, după caz, a unei organizații internaționale umanitare, dacă nu dorește să beneficieze de asistența autorităților din țara sa de origine, ori a reprezentanței organizației internaționale competente, dacă este refugiat sau, din orice alt motiv, se află sub protecția unei astfel de organizații."],"number":"Art. 558"},{"heading":"Anularea renunțării la aplicarea pedepsei","id":"cpp-581-1","intro":"(1) Anularea renunțării la aplicarea pedepsei se dispune, din oficiu sau la sesizarea procurorului, de instanța care judecă ori a judecat în primă instanță infracțiunea ce atrage anularea.","items":["(2) Dacă constată că sunt îndeplinite condițiile art. 82 alin. (3) din Codul penal, instanța, anulând renunțarea la aplicarea pedepsei, dispune condamnarea inculpatului pentru infracțiunea cu privire la care se renunțase la aplicarea pedepsei, stabilește pedeapsa pentru aceasta, aplicând apoi, după caz, dispozițiile cu privire la concursul de infracțiuni, recidivă sau pluralitate intermediară.","(3) La stabilirea pedepsei pentru infracțiunea cu privire la care se anulează renunțarea la aplicarea pedepsei, instanța va avea în vedere exclusiv criteriile de individualizare și circumstanțele din cauza în care s-a pronunțat inițial soluția de renunțare la aplicarea pedepsei. Dispozițiile art. 396 alin. (10) se aplică în mod corespunzător."],"number":"Art. 581¹1"},{"heading":"Revocarea sau anularea amânării aplicării pedepsei","id":"cpp-582","intro":"(1) Asupra revocării sau anulării amânării aplicării pedepsei se pronunță, din oficiu sau la sesizarea procurorului sau a consilierului de probațiune, instanța care judecă ori a judecat în primă instanță infracțiunea ce ar putea atrage revocarea sau anularea.","items":["(2) Dacă până la expirarea termenului prevăzut la art. 86 alin. (4) lit. c) din Codul penal persoana cu privire la care s-a dispus amânarea aplicării pedepsei nu a respectat obligațiile civile stabilite prin hotărârea prin care s-a dispus amânarea, serviciul de probațiune competent sesizează instanța care a pronunțat în primă instanță amânarea, în vederea revocării acesteia. Sesizarea poate fi făcută și de procuror sau de partea interesată, până la expirarea termenului de supraveghere.","(3) Dacă constată că sunt îndeplinite condițiile art. 88 sau 89 din Codul penal, instanța, anulând sau, după caz, revocând amânarea aplicării pedepsei, dispune condamnarea inculpatului și executarea pedepsei stabilite prin hotărârea de amânare, aplicând apoi, după caz, dispozițiile cu privire la concursul de infracțiuni, recidivă sau pluralitate intermediară."],"number":"Art. 582"},{"heading":"Revocarea sau anularea suspendării executării pedepsei sub supraveghere","id":"cpp-583","intro":"(1) Asupra revocării sau anulării suspendării executării pedepsei sub supraveghere prevăzute la art. 96 sau 97 din Codul penal se pronunță, din oficiu, la sesizarea procurorului sau a consilierului de probațiune, instanța care judecă ori a judecat în primă instanță infracțiunea ce ar putea atrage revocarea sau anularea.","items":["(2) Dacă, până la expirarea termenului prevăzut la art. 93 alin. (5) din Codul penal, condamnatul nu a respectat obligațiile civile stabilite prin hotărârea de condamnare, serviciul de probațiune competent sesizează instanța care a pronunțat în primă instanță suspendarea, în vederea revocării acesteia. Sesizarea poate fi făcută și de procuror, de consilierul de probațiune sau de partea interesată, până la expirarea termenului de supraveghere."],"number":"Art. 583"},{"heading":"Înlocuirea pedepsei detențiunii pe viață","id":"cpp-584","intro":"(1) Înlocuirea pedepsei detențiunii pe viață cu pedeapsa închisorii se dispune, la cererea procurorului ori a persoanei condamnate, de către instanța de executare, iar dacă persoana condamnată se află în stare de deținere, de către instanța corespunzătoare în a cărei circumscripție se află locul de deținere.","items":["(2) Hotărârea de înlocuire, rămasă definitivă, se pune în executare potrivit dispozițiilor art. 555-557."],"number":"Art. 584"},{"heading":"Alte modificări de pedepse","id":"cpp-585","intro":"(1) Pedeapsa pronunțată poate fi modificată, dacă la punerea în executare a hotărârii sau în cursul executării pedepsei se constată, pe baza unei alte hotărâri definitive, existența vreuneia dintre următoarele situații:a) concursul de infracțiuni; ... b) recidiva; ... c) pluralitatea intermediară; ... d) acte care intră în conținutul aceleiași infracțiuni. ...","items":["(2) Instanța competentă să dispună asupra modificării pedepsei este instanța de executare a ultimei hotărâri sau, în cazul în care persoana condamnată se află în stare de deținere, instanța corespunzătoare în a cărei circumscripție se află locul de deținere.","(3) Sesizarea instanței se face din oficiu, la cererea procurorului ori a celui condamnat.","(4) La primirea cererii, președintele completului de judecată dispune atașarea la dosar a înscrisurilor și luarea tuturor măsurilor necesare soluționării cauzei."],"number":"Art. 585"},{"heading":"Înlocuirea pedepsei amenzii cu pedeapsa închisorii","id":"cpp-586","intro":"(1) Înlocuirea pedepsei amenzii cu pedeapsa închisorii, în cazul prevăzut la art. 63 din Codul penal, se dispune de instanța de executare.","items":["(2) Sesizarea instanței se face din oficiu sau de către organul care, potrivit legii, execută amenda.","(3) Condamnatul este citat la judecarea sesizării, iar dacă nu are avocat instanța numește unul din oficiu.","(4) Condamnatul privat de libertate va fi adus la judecată.","(5) Hotărârea de înlocuire, rămasă definitivă, se pune în executare potrivit dispozițiilor art. 555-557. În situația în care amenda a însoțit pedeapsa închisorii, se va emite un nou mandat de executare pentru pedeapsa rezultată potrivit art. 63 alin. (2) din Codul penal.","(6) Dacă persoana condamnată achită amenda pe parcursul soluționării cauzei, sesizarea va fi respinsă ca neîntemeiată."],"number":"Art. 586"},{"heading":"Liberarea condiționată","id":"cpp-587","intro":"(1) Liberarea condiționată se dispune, la cererea sau la propunerea făcută potrivit dispozițiilor legii privind executarea pedepselor, de către judecătoria în a cărei circumscripție se află locul de deținere.","items":["(2) Când instanța constată că nu sunt îndeplinite condițiile pentru acordarea liberării condiționate, prin hotărârea de respingere fixează termenul după expirarea căruia propunerea sau cererea va putea fi reînnoită. Termenul nu poate fi mai mare de un an și curge de la rămânerea definitivă a hotărârii.","(3) Hotărârea judecătoriei poate fi atacată cu contestație la tribunalul în a cărei circumscripție se află locul de deținere, în termen de 3 zile de la comunicare. Contestația formulată de procuror este suspensivă de executare.","(4) O copie de pe hotărârea rămasă definitivă se comunică serviciului de probațiune competent, precum și unității de poliție în a cărei circumscripție locuiește cel eliberat."],"number":"Art. 587"},{"heading":"Anularea și revocarea liberării condiționate","id":"cpp-588","intro":"(1) Asupra anulării liberării condiționate prevăzute la art. 105 alin. (1) din Codul penal se pronunță, din oficiu sau la sesizarea procurorului sau a consilierului de probațiune, instanța care judecă ori a judecat în primă instanță infracțiunea care atrage anularea.","items":["(2) Instanța prevăzută la alin. (1) se pronunță și asupra revocării liberării condiționate, în situația prevăzută la art. 104 alin. (2) din Codul penal.","(3) Instanța prevăzută la art. 587 alin. (1) se pronunță și asupra revocării liberării condiționate, în situația prevăzută la art. 104 alin. (1) din Codul penal, la sesizarea serviciului de probațiune, precum și în cazul când instanța care l-a judecat pe condamnat pentru o altă infracțiune nu s-a pronunțat în această privință.","(4) Instanța în fața căreia hotărârea a rămas definitivă este obligată să comunice locului de deținere și serviciului de probațiune, atunci când este cazul, o copie de pe dispozitivul prin care s-a dispus revocarea liberării condiționate."],"number":"Art. 588"},{"heading":"Intervenirea unei legi penale noi","id":"cpp-595","intro":"(1) Când după rămânerea definitivă a hotărârii de condamnare sau a hotărârii prin care s-a aplicat o măsură educativă intervine o lege ce nu mai prevede ca infracțiune fapta pentru care s-a pronunțat condamnarea ori o lege care prevede o pedeapsă sau o măsură educativă mai ușoară decât cea care se execută ori urmează a se executa, instanța ia măsuri pentru aducerea la îndeplinire, după caz, a dispozițiilor art. 4 și 6 din Codul penal.","items":["(2) Aplicarea dispozițiilor alin. (1) se face din oficiu sau la cererea procurorului ori a persoanei condamnate de către instanța de executare, iar dacă persoana condamnată se află în executarea pedepsei sau a unei măsuri educative, de către instanța corespunzătoare în grad în a cărei circumscripție se află locul de deținere sau, după caz, centrul educativ ori centrul de detenție."],"number":"Art. 595"},{"heading":"Amnistia și grațierea","id":"cpp-596","intro":"(1) Aplicarea amnistiei și a grațierii, atunci când intervin după rămânerea definitivă a hotărârii, se face de către judecătorul delegat cu executarea de la instanța de executare, iar dacă cel condamnat se află în executarea pedepsei, de către judecătorul delegat cu executarea de la instanța corespunzătoare în a cărei circumscripție se află locul de deținere.","items":["(2) Judecătorul se pronunță prin încheiere executorie, dată în camera de consiliu, cu participarea procurorului.","(3) Împotriva încheierii pronunțate potrivit alin. (2) se poate declara contestație de către procuror, în termen de 3 zile de la pronunțare. Contestația este suspensivă de executare."],"number":"Art. 596"},{"heading":"Contestația la executare","id":"cpp-598","intro":"(1) Contestația împotriva executării hotărârii penale se poate face în următoarele cazuri:a) când s-a pus în executare o hotărâre care nu era definitivă; ... b) când executarea este îndreptată împotriva altei persoane decât cea prevăzută în hotărârea de condamnare; ... c) când se ivește vreo nelămurire cu privire la hotărârea care se execută sau vreo împiedicare la executare; ... d) când se invocă amnistia, prescripția, grațierea sau orice altă cauză de stingere ori de micșorare a pedepsei. ...","items":["(2) În cazurile prevăzute la alin. (1) lit. a), b) și d), contestația se face, după caz, la instanța prevăzută la art. 597 alin. (1) sau (6), iar în cazul prevăzut la alin. (1) lit. c), la instanța care a pronunțat hotărârea ce se execută. În cazul în care nelămurirea privește o dispoziție dintr-o hotărâre pronunțată în apel sau în recurs în casație, competența revine, după caz, instanței de apel sau Înaltei Curți de Casație și Justiție."],"number":"Art. 598"}]},
  {"id":"l254","title":"Legea nr. 254/2013","scope":"Art. 10–14, 30–43, 45, 51, 53, 60, 76, 95–97 inclusiv 96¹, 115, 120–123, 135–136, 145–148, 152–153, 156, 158, 160 și 179–182","url":"https://legislatie.just.ro/Public/DetaliiDocument/269415","status":"integrat","articles":[{"heading":"Administrația Națională a Penitenciarelor","id":"l254-10","intro":"(1) Administrația Națională a Penitenciarelor este instituția publică cu personalitate juridică, în subordinea Ministerului Justiției, având ca scop coordonarea și controlul activității unităților care se organizează și funcționează în subordinea sa.","items":["(2) Organizarea, funcționarea și atribuțiile Administrației Naționale a Penitenciarelor se stabilesc prin hotărâre a Guvernului.","(3) Conducerea Administrației Naționale a Penitenciarelor este asigurată de un director general, numit prin ordin al ministrului justiției.","(4) Directorul general al Administrației Naționale a Penitenciarelor are calitatea de ordonator secundar de credite.","(5) Finanțarea Administrației Naționale a Penitenciarelor se asigură din subvenții acordate de la bugetul de stat și din venituri proprii."],"number":"Art. 10"},{"heading":"Penitenciarele","id":"l254-11","intro":"(1) Pedeapsa detențiunii pe viață și a închisorii se execută în locuri anume destinate, denumite penitenciare.","items":["(2) Penitenciarele se înființează prin hotărâre a Guvernului, au personalitate juridică și sunt în subordinea Administrației Naționale a Penitenciarelor.","(3) Organizarea și funcționarea penitenciarelor se stabilesc prin regulament aprobat prin ordin al ministrului justiției, care se publică în Monitorul Oficial al României, Partea I.","(4) În cadrul penitenciarelor se pot înființa, prin decizie a directorului general al Administrației Naționale a Penitenciarelor, secții interioare sau exterioare, în raport cu regimurile de executare a pedepselor privative de libertate, categoriile de persoane condamnate și cerințele speciale de protecție a anumitor categorii de deținuți.","(5) Penitenciarul în care persoana condamnată execută pedeapsa privativă de libertate se stabilește de Administrația Națională a Penitenciarelor. La stabilirea penitenciarului se are în vedere ca acesta să fie situat cât mai aproape de localitatea de domiciliu a persoanei condamnate, ținându-se seama și de regimul de executare, măsurile de siguranță ce trebuie luate, nevoile de reintegrare socială identificate, sex și vârstă."],"number":"Art. 11"},{"heading":"Penitenciarele speciale","id":"l254-12","intro":"(1) Pentru anumite categorii de deținuți se pot înființa penitenciare speciale, în condițiile art. 11 alin. (2) și (3).","items":["(2) Penitenciarele speciale sunt:a) penitenciare pentru tineri; ... b) penitenciare pentru femei; ... c) penitenciare-spital. ...","(3) În condițiile art. 11 alin. (2) și (3), se pot stabili penitenciare cu rol de coordonare a penitenciarelor dintr-o zonă geografică.","(4) Atribuțiile penitenciarelor cu rol de coordonare a penitenciarelor dintr-o zonă geografică se stabilesc prin regulamentul de aplicare a prezentei legi."],"number":"Art. 12"},{"heading":"Secțiile speciale de arestare preventivă","id":"l254-13","intro":"În cadrul penitenciarelor se pot înființa secții speciale de arestare preventivă, prin decizie a directorului general al Administrației Naționale a Penitenciarelor.","items":[],"number":"Art. 13"},{"heading":"Secțiile speciale de executare a măsurilor educative privative de libertate","id":"l254-14","intro":"Prin decizie a directorului general al Administrației Naționale a Penitenciarelor se stabilesc penitenciarele în care vor funcționa secții speciale pentru continuarea executării măsurii educative privative de libertate.","items":[],"number":"Art. 14"},{"heading":"Dispoziții generale privind regimurile de executare a pedepselor privative de libertate","id":"l254-30","intro":"(1) Regimurile de executare a pedepselor privative de libertate cuprind ansamblul de reguli care stau la baza executării pedepselor privative de libertate.","items":["(2) Regimurile de executare a pedepselor privative de libertate sunt bazate pe sistemele progresiv și regresiv, persoanele condamnate trecând dintr-un regim în altul, în condițiile prevăzute de prezenta lege.","(3) Regimurile de executare a pedepselor privative de libertate asigură respectarea și protejarea vieții, sănătății și demnității persoanelor condamnate, a drepturilor și libertăților acestora, fără să cauzeze suferințe fizice și nici să înjosească persoana condamnată."],"number":"Art. 30"},{"heading":"Tipurile regimurilor de executare a pedepselor privative de libertate","id":"l254-31","intro":"(1) Regimurile de executare a pedepselor privative de libertate sunt, în ordinea descrescătoare a gradului de severitate, următoarele:a) regimul de maximă siguranță; ... b) regimul închis; ... c) regimul semideschis; ... d) regimul deschis. ...","items":["(2) Regimurile de executare a pedepselor privative de libertate se diferențiază în raport cu gradul de limitare a libertății de mișcare a persoanelor condamnate, modul de acordare a drepturilor și de desfășurare a activităților, precum și cu condițiile de detenție."],"number":"Art. 31"},{"heading":"Comisia pentru stabilirea, individualizarea și schimbarea regimului de executare a pedepselor privative de libertate","id":"l254-32","intro":"(1) În fiecare penitenciar se constituie o comisie pentru stabilirea, individualizarea și schimbarea regimului de executare a pedepselor privative de libertate, alcătuită din: directorul penitenciarului, care este și președintele comisiei, șeful serviciului sau biroului pentru aplicarea regimurilor și șeful serviciului sau biroului educație ori șeful serviciului sau biroului asistență psihosocială.","items":["(2) Secretariatul comisiei prevăzute la alin. (1) se asigură de către șeful serviciului sau biroului evidență din penitenciarul respectiv.","(3) Comisia pentru individualizarea regimului de executare a pedepselor privative de libertate își desfășoară activitatea, de regulă, o dată pe săptămână."],"number":"Art. 32"},{"heading":"Aplicarea provizorie a regimului de executare","id":"l254-33","intro":"(1) După terminarea perioadei de carantină și observare prevăzute la art. 44, persoanei condamnate căreia nu i s-a stabilit regimul de executare i se aplică provizoriu regimul de executare corespunzător cuantumului pedepsei pe care o execută, potrivit art. 34 alin. (1), art. 35 alin. (1), art. 36 alin. (1), art. 37 alin. (1) și art. 38 alin. (1).","items":["(2) În cazul persoanelor inițial arestate preventiv, regimul provizoriu se aplică de la momentul primirii mandatului de executare a pedepsei, până la prima întrunire a comisiei prevăzute la art. 32.","(3) Aplicarea regimului provizoriu se face în baza deciziei directorului penitenciarului, care este executorie și definitivă.","(4) Regimul de executare stabilit pentru persoanele condamnate și arestate preventiv în altă cauză se suspendă până la încetarea arestului preventiv. Pe perioada de suspendare se aplică regimul specific arestaților preventiv."],"number":"Art. 33"},{"heading":"Regimul de maximă siguranță","id":"l254-34","intro":"(1) Regimul de maximă siguranță se aplică inițial persoanelor condamnate la pedeapsa detențiunii pe viață și persoanelor condamnate la pedeapsa închisorii mai mare de 13 ani, precum și celor care prezintă risc pentru siguranța penitenciarului.","items":["(2) Criteriile de stabilire și procedura de evaluare a riscului pe care îl prezintă persoana condamnată pentru siguranța penitenciarului se stabilesc prin regulamentul de aplicare a prezentei legi.","(3) În mod excepțional, natura și modul de săvârșire a infracțiunii, precum și persoana condamnatului pot determina includerea persoanei condamnate în regimul de executare imediat inferior ca grad de severitate, în condițiile stabilite prin regulamentul de aplicare a prezentei legi.","(4) Persoanele condamnate care execută pedeapsa în regim de maximă siguranță sunt supuse unor măsuri stricte de pază, supraveghere și escortare, sunt cazate, de regulă, individual, prestează muncă și desfășoară activități educative, culturale, terapeutice, de consiliere psihologică și asistență socială, moral-religioase, instruire școlară și formare profesională, în grupuri mici, în spații anume stabilite în interiorul penitenciarului, sub supraveghere continuă, în condițiile stabilite prin regulamentul de aplicare a prezentei legi."],"number":"Art. 34"},{"heading":"Categorii de persoane cărora nu li se aplică regimul de maximă siguranță","id":"l254-35","intro":"(1) Regimul de maximă siguranță nu se aplică următoarelor persoane condamnate:a) care au împlinit vârsta de 65 de ani; ... b) femeilor însărcinate sau care au în îngrijire un copil în vârstă de până la un an; ... c) persoanelor încadrate în gradul I de invaliditate, precum și celor cu afecțiuni locomotorii grave. ...","items":["(2) Persoanele condamnate prevăzute la alin. (1) lit. a) execută pedeapsa privativă de libertate în regim închis. Persoanele condamnate prevăzute la alin. (1) lit. b) și c) execută pedeapsa privativă de libertate în regim închis, pe perioada cât durează cauza care a impus neaplicarea regimului de maximă siguranță.","(3) La data încetării cauzei care a determinat neaplicarea regimului de maximă siguranță, situația persoanei condamnate este analizată în condițiile art. 40.","(4) Prevederile alin. (1) nu se aplică persoanelor condamnate care prezintă risc pentru siguranța penitenciarului, stabilit ca atare, potrivit criteriilor și procedurii de evaluare a riscului prevăzute de regulamentul de aplicare a prezentei legi."],"number":"Art. 35"},{"heading":"Regimul închis","id":"l254-36","intro":"(1) Regimul închis se aplică inițial persoanelor condamnate la pedeapsa închisorii mai mare de 3 ani, dar care nu depășește 13 ani.","items":["(2) În mod excepțional, natura și modul de săvârșire a infracțiunii, persoana condamnatului, precum și comportarea acesteia până la stabilirea regimului de executare pot determina includerea persoanei condamnate în regimul de executare imediat inferior sau superior ca grad de severitate, în condițiile stabilite prin regulamentul de aplicare a prezentei legi.","(3) Persoanele condamnate care execută pedeapsa în regim închis sunt cazate, de regulă, în comun, prestează muncă și desfășoară activități educative, culturale, terapeutice, de consiliere psihologică și asistență socială, moral-religioase, instruire școlară și formare profesională, în grupuri, în interiorul penitenciarului, sub pază și supraveghere, în condițiile stabilite prin regulamentul de aplicare a prezentei legi.","(4) Persoanele condamnate care execută pedeapsa în regim închis pot presta munca și pot desfășura activități educative și culturale în afara penitenciarului, sub pază și supraveghere continuă, cu aprobarea directorului penitenciarului.","(5) Măsurile de siguranță specifice regimului închis se aplică persoanelor condamnate, altele decât cele din regimul de maximă siguranță, transferate temporar într-un alt penitenciar, pentru prezentarea în fața organelor judiciare.","(6) Măsurile de siguranță specifice regimului închis se aplică deținuților internați în penitenciare-spital și în infirmeria penitenciarului."],"number":"Art. 36"},{"heading":"Regimul semideschis","id":"l254-37","intro":"(1) Regimul semideschis se aplică inițial persoanelor condamnate la pedeapsa închisorii mai mare de un an, dar care nu depășește 3 ani.","items":["(2) În mod excepțional, natura și modul de săvârșire a infracțiunii, persoana condamnatului, precum și comportarea acesteia până la stabilirea regimului de executare pot determina includerea persoanei condamnate în regimul de executare imediat inferior sau imediat superior ca grad de severitate, în condițiile stabilite prin regulamentul de aplicare a prezentei legi.","(3) Persoanele condamnate care execută pedeapsa în regim semideschis sunt cazate în comun, se pot deplasa neînsoțite în zone prestabilite din interiorul penitenciarului, prestează muncă și desfășoară activități educative, culturale, terapeutice, de consiliere psihologică și asistență socială, moral-religioase, instruire școlară și formare profesională, sub supraveghere, în grupuri, în spații din interiorul penitenciarului care rămân deschise în timpul zilei, în condițiile stabilite prin regulamentul de aplicare a prezentei legi.","(4) Persoanele condamnate care execută pedeapsa în regim semideschis pot presta muncă și desfășura activități educative, culturale, terapeutice, de consiliere psihologică și asistență socială, moral-religioase, instruire școlară și formare profesională, în afara penitenciarului, sub supraveghere inclusiv electronică. Supravegherea îndeplinirii obligației de a purta permanent un dispozitiv electronic de supraveghere se face în condițiile stabilite prin lege specială."],"number":"Art. 37"},{"heading":"Regimul deschis","id":"l254-38","intro":"(1) Regimul deschis se aplică inițial persoanelor condamnate la pedeapsa închisorii de cel mult un an.","items":["(2) În mod excepțional, natura și modul de săvârșire a infracțiunii, persoana condamnatului, precum și comportarea acesteia până la stabilirea regimului de executare pot determina includerea persoanei condamnate în regimul de executare imediat superior ca grad de severitate, în condițiile stabilite prin regulamentul de aplicare a prezentei legi.","(3) Persoanele condamnate care execută pedeapsa în regim deschis sunt cazate în comun, se pot deplasa neînsoțite în zone prestabilite din interiorul penitenciarului, pot presta munca și pot desfășura activități educative, culturale, terapeutice, de consiliere psihologică și asistență socială, moral-religioase, instruire școlară și formare profesională, în afara penitenciarului, fără supraveghere, în condițiile stabilite prin regulamentul de aplicare a prezentei legi.","(4) Persoanele condamnate din regimul deschis sunt analizate în comisia prevăzută la art. 32 numai dacă se impune schimbarea regimului de executare într-unul superior ca grad de severitate."],"number":"Art. 38"},{"heading":"Stabilirea regimului de executare a pedepselor privative de libertate","id":"l254-39","intro":"(1) Regimul de executare a pedepsei privative de libertate se stabilește de către comisia prevăzută la art. 32 la prima întrunire a acesteia, după terminarea perioadei de carantină și observare sau după aplicarea regimului provizoriu.","items":["(2) La stabilirea regimului de executare se au în vedere următoarele criterii:a) durata pedepsei privative de libertate; ... b) gradul de risc al persoanei condamnate; ... c) antecedentele penale; ... d) vârsta și starea de sănătate ale persoanei condamnate; ... e) conduita persoanei condamnate, pozitivă sau negativă, inclusiv în perioadele de detenție anterioare; ... f) nevoile identificate și abilitățile persoanei condamnate, necesare includerii în programe educaționale, de asistență psihologică și asistență socială; ... g) disponibilitatea persoanei condamnate de a presta muncă și de a participa la activități educative, culturale, terapeutice, de consiliere psihologică și asistență socială, moral-religioase, instruire școlară și formare profesională. ...","(3) Decizia de stabilire a regimului de executare a pedepselor privative de libertate se comunică persoanei condamnate împreună cu menționarea căii de atac existente și a termenului de exercitare a acesteia. Împotriva modului de stabilire a regimului de executare, persoana condamnată poate formula plângere la judecătorul de supraveghere a privării de libertate, în termen de 3 zile de la data la care i s-a comunicat decizia de stabilire a regimului de executare a pedepselor privative de libertate.","(4) Plângerea nu suspendă executarea hotărârii comisiei.","(5) Persoana condamnată poate fi ascultată, la locul de deținere, de judecătorul de supraveghere a privării de libertate.","(6) Judecătorul de supraveghere a privării de libertate soluționează plângerea în termen de 10 zile de la data primirii acesteia și pronunță, prin încheiere motivată, una dintre următoarele soluții:a) admite plângerea și dispune modificarea regimului de executare stabilit de comisia prevăzută la art. 32; ... b) respinge plângerea, dacă aceasta este nefondată, tardivă sau inadmisibilă; ... c) ia act de retragerea plângerii. ...","(7) Încheierea judecătorului de supraveghere a privării de libertate se comunică persoanei condamnate și administrației penitenciarului, în termen de 3 zile de la data pronunțării acesteia.","(8) Încheierea este executorie de la data comunicării către administrația penitenciarului.","(9) Competența de soluționare a plângerii aparține judecătorului de supraveghere a privării de libertate de la penitenciarul a cărui comisie a stabilit regimul de executare.","(10) Împotriva încheierii judecătorului de supraveghere a privării de libertate, persoana condamnată și administrația penitenciarului pot formula contestație la judecătoria în a cărei circumscripție se află penitenciarul, în termen de 3 zile de la comunicarea încheierii.","(11) Contestațiile se depun la judecătorul de supraveghere a privării de libertate care a pronunțat încheierea.","(12) Contestațiile se înaintează judecătoriei, împreună cu dosarul cauzei, în termen de două zile de la primirea acestora.","(13) Contestația nu suspendă executarea încheierii.","(14) Contestația se judecă, în ședință publică, cu citarea persoanei condamnate și a administrației penitenciarului.","(15) Persoana condamnată și administrația penitenciarului pot depune memorii și concluzii scrise.","(16) Persoana condamnată este adusă la judecată doar la solicitarea instanței, în acest caz fiind audiată.","(17) Asistența juridică nu este obligatorie. În cazul în care procurorul și reprezentantul administrației penitenciarului participă la judecată, aceștia pun concluzii.","(18) Instanța se pronunță prin sentință definitivă, în ședință publică.","(19) Sentința se comunică persoanei condamnate și administrației penitenciarului."],"number":"Art. 39"},{"heading":"Schimbarea regimului de executare a pedepselor privative de libertate","id":"l254-40","intro":"(1) Schimbarea regimului de executare a pedepselor privative de libertate se dispune de comisia prevăzută la art. 32.","items":["(2) Comisia prevăzută la art. 32 are obligația ca, după executarea a 6 ani și 6 luni, în cazul pedepselor cu detențiunea pe viață, și a unei cincimi din durata pedepsei cu închisoarea, precum și în situația prevăzută la art. 35 alin. (3), să analizeze conduita persoanei condamnate și eforturile pentru reintegrare socială, întocmind un raport care se aduce la cunoștința persoanei condamnate, sub semnătură.","(3) Comisia prevăzută la art. 32 va dispune schimbarea regimului de maximă siguranță în regim închis în cazul persoanelor condamnate care au împlinit vârsta de 65 de ani.","(4) În activitatea sa, comisia ține cont și de rezultatele aplicării instrumentelor-standard de evaluare a activităților desfășurate de deținuți, aprobate prin decizie a directorului general al Administrației Naționale a Penitenciarelor.","(5) Schimbarea regimului de executare a pedepselor privative de libertate în regimul imediat inferior ca grad de severitate se poate dispune, ținându-se seama de natura și modul de săvârșire a infracțiunii, dacă persoana condamnată:a) a avut o bună conduită, stabilită prin raportare la recompensele acordate și sancțiunile aplicate și nu a recurs la acțiuni care indică o constantă negativă a comportamentului; ... b) a întreprins eforturile necesare în cadrul muncii prestate sau s-a implicat activ în activitățile stabilite în Planul individualizat de evaluare și intervenție educativă și terapeutică. ...","(6) Schimbarea regimului de executare a pedepselor privative de libertate într-unul mai sever se poate dispune, în orice moment al executării pedepsei, dacă persoana condamnată a comis o infracțiune sau a fost sancționată disciplinar pentru o abatere disciplinară foarte gravă sau pentru mai multe abateri disciplinare grave.","(7) Dacă persoana condamnată a fost inclusă în categoria celor cu grad de risc pentru siguranța penitenciarului, în condițiile art. 34 alin. (1) teza finală, se dispune schimbarea regimului de executare a pedepselor privative de libertate în regimul de maximă siguranță.","(8) Hotărârea comisiei prevăzute la art. 32, prin care se dispune menținerea sau schimbarea regimului de executare, cuprinde și termenul de reanalizare care nu poate fi mai mare de un an.","(9) Comisia prevăzută la art. 32 are obligația de a analiza, periodic, situația persoanei condamnate, la împlinirea termenului stabilit conform prevederilor alin. (8).","(10) În cazul în care unei persoane condamnate i s-a schimbat regimul de executare în condițiile alin. (7), trecerea în regimul imediat inferior ca grad de severitate, potrivit art. 31, se poate face numai după executarea fracțiunilor prevăzute la alin. (2) sau, după caz, la împlinirea termenului stabilit la alin. (8).","(11) Hotărârea de schimbare a regimului de executare a pedepselor privative de libertate se comunică persoanei condamnate împreună cu menționarea căii de atac existente și a termenului de exercitare a acesteia. Împotriva hotărârii comisiei, persoana condamnată poate formula plângere la judecătorul de supraveghere a privării de libertate, în termen de 3 zile de la data la care i s-a comunicat hotărârea.","(12) Persoana condamnată poate fi ascultată, la locul de deținere, de judecătorul de supraveghere a privării de libertate.","(13) Judecătorul de supraveghere a privării de libertate soluționează plângerea în termen de 10 zile de la data primirii acesteia și pronunță, prin încheiere motivată, una dintre următoarele soluții:a) admite plângerea, dispunând asupra modificării regimului de executare stabilit de comisia prevăzută la art. 32; ... b) respinge plângerea, dacă aceasta este nefondată, tardivă sau inadmisibilă; ... c) ia act de retragerea plângerii. ...","(14) Prin încheiere, judecătorul de supraveghere a privării de libertate fixează termenul de reanalizare, care nu poate fi mai mare de un an. Termenul curge de la data emiterii hotărârii comisiei prevăzute la art. 32.","(15) Încheierea judecătorului de supraveghere a privării de libertate se comunică persoanei condamnate și administrației penitenciarului, în termen de 3 zile de la data pronunțării acesteia.","(16) Încheierea este executorie de la data comunicării către administrația penitenciarului.","(17) Competența de soluționare a plângerii aparține judecătorului de supraveghere a privării de libertate de la penitenciarul a cărui comisie a dispus menținerea sau schimbarea regimului de executare.","(18) Împotriva încheierii judecătorului de supraveghere a privării de libertate, persoana condamnată și administrația penitenciarului pot formula contestație la judecătoria în a cărei circumscripție se află penitenciarul, în termen de 3 zile de la comunicarea încheierii.","(19) Contestațiile se depun la judecătorul de supraveghere a privării de libertate care a pronunțat încheierea.","(20) Contestațiile se înaintează judecătoriei, împreună cu dosarul cauzei, în termen de două zile de la primirea acestora.","(21) Contestația nu suspendă executarea încheierii.","(22) Dispozițiile art. 39 alin. (14)-(19) se aplică în mod corespunzător."],"number":"Art. 40"},{"heading":"Individualizarea regimului de executare a pedepselor privative de libertate","id":"l254-41","intro":"(1) Individualizarea regimului de executare a pedepselor privative de libertate se stabilește de comisia prevăzută la art. 32, în funcție de durata condamnării, conduita, personalitatea, gradul de risc, vârsta, starea de sănătate, nevoile identificate și posibilitățile de reintegrare socială a persoanei condamnate.","items":["(2) Persoana condamnată este inclusă, ținând seama de criteriile prevăzute la alin. (1), în activități educative, culturale, terapeutice, de consiliere psihologică și asistență socială, moral-religioase, instruire școlară și formare profesională.","(3) Activitățile prevăzute la alin. (2) sunt realizate de personalul serviciilor de educație și asistență psihosocială din cadrul penitenciarelor, cu participarea, după caz, a consilierilor de probațiune, a voluntarilor, a asociațiilor și fundațiilor, precum și a altor reprezentanți ai societății civile.","(4) Pentru fiecare persoană condamnată, specialiștii serviciului de educație și asistență psihosocială întocmesc un Plan individualizat de evaluare și intervenție educativă și terapeutică, în care consemnează activitățile și programele recomandate, în funcție de riscurile și nevoile identificate."],"number":"Art. 41"},{"heading":"Individualizarea regimului de executare a pedepselor privative de libertate în cazul tinerilor","id":"l254-42","intro":"(1) Tinerii condamnați sunt incluși, pe durata executării pedepsei, în programe speciale educaționale, de asistență psihologică și asistență socială, în funcție de vârsta și de personalitatea fiecăruia. În sensul prezentei legi, se consideră tineri persoanele condamnate care nu au împlinit vârsta de 21 de ani.","items":["(2) La mutarea într-un penitenciar de adulți a tinerilor condamnați, sunt reevaluate nevoile de educație și asistență psihosocială ale persoanei condamnate.","(3) Programele speciale prevăzute la alin. (1) sunt realizate de personalul serviciilor de educație și asistență psihosocială din cadrul penitenciarelor, cu participarea consilierilor de probațiune, a voluntarilor, a asociațiilor și fundațiilor, precum și a altor reprezentanți ai societății civile.","(4) Dispozițiile art. 57 se aplică în mod corespunzător în cazul persoanelor condamnate prevăzute la alin. (1)."],"number":"Art. 42"},{"heading":"Primirea persoanelor condamnate","id":"l254-43","intro":"(1) Primirea în penitenciar a persoanelor condamnate se face oricând, pe baza mandatului de executare a pedepsei privative de libertate, după stabilirea identității acestora. Persoanele condamnate se depun în penitenciarul cel mai apropiat de locul în care acestea au fost arestate sau deținute, indiferent de profilarea penitenciarului, cu respectarea principiului separației pe sexe și pe vârste, respectiv majori sau minori.","items":["(2) Persoanele condamnate sunt primite de la organele de executare a mandatului de executare a pedepselor privative de libertate, în condițiile și cu documentele prevăzute în regulamentul de aplicare a prezentei legi, constituite într-un dosar.","(3) Primirea persoanelor condamnate se face în spații special amenajate, femeile fiind separate de bărbați.","(4) Îndată după primirea în penitenciar, persoana condamnată are dreptul de a încunoștința personal sau de a solicita administrației să încunoștințeze un membru al familiei sau o altă persoană desemnată de aceasta, despre penitenciarul în care se află.","(5) Administrația penitenciarului are obligația de a aduce la cunoștința persoanei condamnate dispozițiile alin. (4), precum și de a consemna într-un proces-verbal modul în care s-a realizat încunoștințarea.","(6) Dacă persoana condamnată nu este cetățean român, aceasta are și dreptul de a încunoștința sau de a solicita încunoștințarea misiunii diplomatice ori a oficiului consular al statului al cărui cetățean este sau, după caz, a unei organizații internaționale umanitare, dacă nu dorește să beneficieze de asistența autorităților din țara sa de origine ori a reprezentanței organizației internaționale competente, dacă este refugiat sau, din orice alt motiv, se află sub protecția unei astfel de organizații.","(7) Măsurile ce se dispun la primirea în penitenciar a persoanelor condamnate sunt realizate în următoarea ordine:a) efectuarea percheziției corporale amănunțite; ... b) întocmirea unui inventar al bunurilor personale; ... c) efectuarea unui examen clinic general de către personalul de specialitate al penitenciarului, al cărui rezultat este consemnat în fișa medicală; ... d) prelevarea amprentelor, urmând ca aceste date să fie transmise și stocate pe suport hârtie în dosarul individual al persoanei condamnate și în format electronic în baza de date națională de comparare a amprentelor; ... e) fotografierea, în vederea operaționalizării documentelor de evidență; ... f) informarea persoanei condamnate cu privire la drepturile, obligațiile și interdicțiile persoanelor condamnate, precum și cu privire la recompensele care pot fi acordate, abateri și sancțiuni disciplinare care pot fi aplicate; ... g) intervievarea, în vederea stabilirii nevoilor imediate ale persoanei condamnate. ...","(8) În cazul în care persoana condamnată nu vorbește sau nu înțelege limba română ori nu se poate exprima, administrația penitenciarului dispune măsurile necesare aducerii la cunoștință a informațiilor prevăzute la alin. (4), întocmindu-se un proces-verbal în acest sens.","(9) În cazul cetățenilor români aparținând minorităților naționale, informarea prevăzută la alin. (4) se poate face în limba lor maternă.","(10) În cazul în care persoana condamnată prezintă dizabilități, administrația penitenciarului dispune măsurile necesare executării, de către aceasta, a pedepsei, în condiții care să respecte demnitatea umană."],"number":"Art. 43"},{"heading":"Transferarea persoanelor condamnate","id":"l254-45","intro":"(1) Transferarea persoanelor condamnate în alt penitenciar, ca urmare a stabilirii provizorii a regimului de executare, se dispune de către directorul penitenciarului, conform profilării penitenciarelor stabilite prin decizie a directorului general al Administrației Naționale a Penitenciarelor.","items":["(2) Transferarea persoanelor condamnate în alt penitenciar, ca urmare a stabilirii sau schimbării regimului de executare a pedepselor privative de libertate sau pentru alte motive întemeiate, se dispune, la propunerea comisiei prevăzute la art. 32 sau la cererea persoanei condamnate, cu avizul comisiei prevăzute la art. 32, de către directorul general al Administrației Naționale a Penitenciarelor.","(3) Transferarea persoanelor condamnate în alt penitenciar, dacă este necesară activității unui organ judiciar, se dispune, la solicitarea organului judiciar, de către directorul penitenciarului iar, în cazul persoanelor condamnate solicitate de mai multe organe judiciare în aceeași perioadă de timp, transferarea temporară se dispune de către directorul general al Administrației Naționale a Penitenciarelor.","(4) Directorul general al Administrației Naționale a Penitenciarelor dispune transferarea temporară în situația prevăzută la alin. (3), ținând cont de următoarele criterii:a) cauzele penale în care, pentru persoanele condamnate, au fost emise mandate de arestare preventivă; ... b) cauzele penale au prioritate față de cauzele civile; ... c) instanțele judecătorești au prioritate față de celelalte organe judiciare; ... d) gradul de jurisdicție a organului judiciar care instrumentează cauza; ... e) netransferarea ar afecta grav urmărirea penală sau judecata. ...","(5) Cu ocazia primirii citației de către persoana condamnată în cadrul unei proceduri judiciare declanșate de aceasta, în măsura în care condamnatul contestă inițierea acestui demers judiciar, cererea condamnatului de nerecunoaștere sau de retragere a cererii urmează a fi transmisă de îndată, prin grija administrației penitenciarului, instanței sau parchetului învestit.","(6) Transferarea deținuților în centrele de reținere și arestare preventivă ce funcționează în subordinea Ministerului Afacerilor Interne, necesară activității organelor judiciare, se face cu aprobarea directorului penitenciarului și informarea judecătorului de supraveghere a privării de libertate. Perioada și motivele de transfer fac parte din adresa scrisă și semnată, după caz, de șefii Inspectoratului General al Poliției Române, inspectoratelor județene de poliție, directorul general al Direcției Generale de Poliție a Municipiului București sau al Direcției Generale Anticorupție, avizată de procuror. La expirarea perioadei, deținutul este depus la penitenciarul de unde a fost transferat.","(7) Dispozițiile art. 43 alin. (4) și (5) se aplică în mod corespunzător.","(8) Este interzisă transferarea în penitenciare, pentru o perioadă mai mare de 10 zile, a persoanelor care execută măsura educativă a internării într-un centru educativ sau într-un centru de detenție. Dispozițiile art. 36 alin. (5) se aplică în mod corespunzător.","(9) Abrogat."],"number":"Art. 45"},{"heading":"Ascultarea persoanelor condamnate de către autorități ale statului","id":"l254-51","intro":"(1) Ascultarea persoanelor condamnate în penitenciare se poate face de către reprezentanți ai structurilor Ministerului Afacerilor Interne, cu aprobarea sau în baza delegației semnate de procurorul care supraveghează sau efectuează urmărirea penală, ori, după caz, de către șefii structurilor din cadrul Poliției Române, Poliției de Frontieră Române, Direcției Generale Anticorupție, cu funcție de reprezentare până la nivel de șef birou.","items":["(2) Ascultarea persoanelor condamnate în incinta penitenciarului se poate face și de către:a) procuror, în exercitarea atribuțiilor de serviciu, pe baza împuternicirii conducătorului instituției; ... b) senatori sau deputați ai Parlamentului României, cu împuternicire din partea comisiei din care fac parte; ... c) europarlamentari, cu împuternicire din partea comisiei din care fac parte; ... d) reprezentanții serviciilor de probațiune, în exercitarea atribuțiilor de serviciu; ... e) orice altă persoană abilitată prin lege, împuternicită de conducătorul instituției din care face parte; ... f) persoane care desfășoară activități liberale, care reprezintă autoritățile statului. ...","(3) Identitatea și calitatea persoanelor prevăzute la alin. (1) și (2) se dovedesc cu actul de identitate și legitimația de serviciu.","(4) Ascultarea persoanelor condamnate în situațiile prevăzute la alin. (1) și (2) se face în condiții de confidențialitate.","(5) Prevederile art. 18 alin. (2) și (3) se aplică în mod corespunzător."],"number":"Art. 51"},{"heading":"Punerea în libertate","id":"l254-53","intro":"(1) Punerea în libertate se dispune, de îndată, la expirarea duratei pedepsei închisorii, la data rămânerii definitive a hotărârii prin care s-a dispus liberarea condiționată, precum și la orice altă dată hotărâtă de organele judiciare competente, în situațiile anume prevăzute de lege, cu precizarea în registrul de evidență a executării punerii în libertate, prin indicarea datei și orei de ieșire din penitenciar. Administrația penitenciarului comunică punerea în libertate organului judiciar care a dispus măsura și, dacă este cazul, celui care controlează executarea măsurilor de supraveghere și obligațiilor dispuse potrivit Codului penal.","items":["(2) Administrația penitenciarului are obligația de a comunica persoanei vătămate punerea în libertate a deținutului la data executării în întregime a pedepsei, în conformitate cu dispozițiile art. 404 alin. (6) din Codul de procedură penală, la datele de contact furnizate de persoana vătămată în cursul procesului penal și transmise distinct de instanța de executare odată cu transmiterea hotărârii de condamnare și a mandatului de executare. În cazul în care punerea în libertate a făptuitorului are loc înainte de împlinirea termenului de executare a pedepsei sau a măsurilor preventive privative de libertate, informarea părții vătămate o realizează organul judiciar care a dispus liberarea, sau după caz, instanța de executare. În cazul permisiunii de ieșire din penitenciar, al desfășurării activităților de către deținuții din regim deschis, care se deplasează neînsoțit în exteriorul locului de deținere, precum și în situația producerii unei evadări, informarea părții vătămate o realizează organul de poliție sesizat de către administrația locului de deținere.","(2^1) Atunci când, odată cu acordarea liberării condiționate, instanța impune condamnatului să execute obligația prevăzută la art. 101 alin. (2) lit. e) din Legea nr. 286/2009 privind Codul penal, cu modificările și completările ulterioare, informarea persoanei vătămate conform alin. (2) se va face și asupra acestei obligații, precum și a duratei sale.","(3) La punerea în libertate, persoanei condamnate i se efectuează un examen clinic general, rezultatul examenului înscriindu-se în fișa medicală a persoanei condamnate, i se restituie bunurile și actele personale și îi sunt prelevate probe biologice, în condițiile legii, în vederea introducerii profilurilor genetice în sistemul național de date genetice judiciare.","(4) În situația în care persoanele condamnate nu dispun de mijloace bănești la punerea în libertate și au domiciliul sau reședința în România, Administrația Națională a Penitenciarelor va asigura acestora contravaloarea transportului până la domiciliu sau reședință, la nivelul tarifelor practicate de Compania Națională de Căi Ferate \"C.F.R\" - S.A."],"number":"Art. 53"},{"heading":"Dreptul la consultarea documentelor cu caracter personal","id":"l254-60","intro":"(1) Persoana condamnată, apărătorul acesteia sau oricare altă persoană, cu acordul scris al persoanei condamnate, are acces la dosarul individual.","items":["(2) Persoana condamnată poate obține, la cerere, contra cost, într-un număr de exemplare justificat, fotocopii ale documentelor din dosarul individual.","(3) Dacă persoanele condamnate nu dispun de mijloacele bănești necesare, cheltuielile prevăzute la alin. (2) sunt suportate de către administrația locului de deținere.","(4) Sunt considerate persoane fără mijloace bănești persoanele condamnate care nu au sau nu au avut în ultimele 30 de zile sume de bani disponibile în fișa contabilă nominală sau în contul personal. Sumele cheltuite de administrația penitenciarului pentru exercitarea dreptului la petiționare sau corespondență se recuperează ulterior de la persoana condamnată din sumele ce le va deține în fișa contabilă nominală sau în contul personal, în timpul executării pedepsei.","(5) Apărătorul sau oricare altă persoană, cu acordul scris al persoanei condamnate, poate obține, contra cost, o fotocopie a documentelor din dosarul individual.","(6) Dosarul individual poate fi consultat, cu excepția situațiilor în care acesta este solicitat de organele abilitate potrivit legii, numai cu acordul persoanei condamnate.","(7) Consultarea documentelor din dosarul individual prevăzut la alin. (1) se face în prezența unei persoane desemnate de directorul penitenciarului.","(8) Datele cu caracter personal ale persoanelor condamnate sunt confidențiale, potrivit legii."],"number":"Art. 60"},{"heading":"Dreptul de a vota","id":"l254-76","intro":"(1) Persoanele condamnate își pot exercita dreptul de a vota, dacă acesta nu a fost interzis prin hotărârea de condamnare.","items":["(2) Administrația penitenciarului asigură persoanelor condamnate condițiile necesare exercitării dreptului la vot, potrivit legii.","(3) Șeful serviciului public comunitar de evidență a persoanelor acordă scutire de la plata cheltuielilor de producere și de eliberare a actelor de identitate, în situația în care persoanele condamnate nu dispun de mijloace financiare."],"number":"Art. 76"},{"heading":"Condițiile de acordare a liberării condiționate","id":"l254-95","intro":"Persoana condamnată poate fi liberată condiționat înainte de executarea în întregime a pedepsei privative de libertate, dacă îndeplinește condițiile prevăzute la art. 99 sau, după caz, la art. 100 din Codul penal.","items":[],"number":"Art. 95"},{"heading":"Partea din durata pedepsei care este considerată ca executată pe baza muncii prestate și/sau a instruirii școlare și formării profesionale","id":"l254-96","intro":"(1) Pedeapsa care este considerată ca executată pe baza muncii prestate sau a instruirii școlare și formării profesionale, în vederea acordării liberării condiționate, se calculează după cum urmează:a) în cazul în care se prestează o muncă remunerată, se consideră 5 zile executate pentru 4 zile de muncă; ... b) în cazul în care se prestează o muncă neremunerată, se consideră 4 zile executate pentru 3 zile de muncă; ... c) în cazul în care munca este prestată pe timpul nopții, se consideră 3 zile executate pentru două nopți de muncă; ... d) în cazul participării la cursurile de școlarizare pentru formele de învățământ general obligatoriu, se consideră 30 de zile executate pentru absolvirea unui an școlar; ... e) în cazul participării la cursurile de calificare ori recalificare profesională, se consideră 20 de zile executate pentru absolvirea unui curs de calificare ori recalificare profesională; ... f) în cazul elaborării de lucrări științifice publicate sau invenții brevetate, se consideră 20 de zile executate, indiferent de numărul lucrărilor științifice sau al invențiilor realizate, pentru întreaga durată a executării pedepsei, inclusiv în cazul pedepselor contopite. ...","items":["(2) Reducerea fracțiunii de pedeapsă care este considerată ca executată pe baza muncii prestate sau a instruirii școlare și formării profesionale nu poate fi revocată."],"number":"Art. 96"},{"heading":"Procedura elaborării de lucrări științifice publicate sau invenții brevetate","id":"l254-96-1","intro":"(1) Caracterul științific al lucrărilor elaborate de către deținuți este stabilit, potrivit dispozițiilor legale, de către Consiliul Național al Cercetării Științifice, denumit în continuare CNCS, cu sprijinul logistic al Unității Executive pentru Finanțarea Învățământului Superior, a Cercetării, Dezvoltării și Inovării, denumită în continuare UEFISCDI.","items":["(2) Brevetarea invențiilor se realizează, potrivit dispozițiilor legale, de către Oficiul de Stat pentru Invenții și Mărci, denumit în continuare OSIM.","(3) Lucrările științifice sau invențiile brevetate pot fi elaborate de către deținuți în condițiile stabilite în prezenta lege și prin regulamentul de aplicare a prezentei legi, care se completează, după caz, cu prevederile legale privind evaluarea lucrărilor științifice de către CNCS cu sprijinul logistic al UEFISCDI, respectiv procedurile efectuate de OSIM cu privire la cererile de brevet de invenție.","(4) Pe durata elaborării de lucrări științifice sau de invenții pot fi desfășurate activități lucrative, fără ca acestea să se suprapună și fără ca, însumată, durata desfășurării tuturor acestor activități să depășească durata prevăzută de legislația muncii.","(5) Lucrările științifice se pot elabora numai în domeniile și specializările universitare stabilite de nomenclatorul domeniilor și al specializărilor/programelor de studii universitare.","(6) În cazul lucrărilor științifice sau invențiilor brevetate realizate în coautorat, numărul zilelor considerate ca executate se împarte proporțional la numărul de coautori. În cazul în care mai mulți coautori sunt persoane private de libertate, procedura se aplică în mod individual fiecărui coautor.","(7) Comisia pentru liberare condiționată sesizată potrivit legii, în vederea analizării acordării zilelor considerate ca executate, ia la cunoștință de acordarea caracterului științific, respectiv brevetarea invenției, potrivit alin. (1) și (2), și verifică respectarea procedurii de elaborare a lucrării științifice publicate, respectiv invenției brevetate.","(8) O nouă solicitare privind elaborarea unei lucrări științifice sau invenții se poate formula doar după finalizarea lucrării anterioare."],"number":"Art. 96¹1"},{"heading":"Procedura de acordare a liberării condiționate","id":"l254-97","intro":"(1) Liberarea condiționată se acordă potrivit procedurii prevăzute în Codul de procedură penală, la cererea persoanei condamnate sau la propunerea comisiei pentru liberare condiționată.","items":["(2) Comisia pentru liberare condiționată este alcătuită din judecătorul de supraveghere a privării de libertate, care este și președintele comisiei, directorul penitenciarului, directorul adjunct pentru siguranța deținerii și regim penitenciar, directorul adjunct pentru educație și asistență psihosocială și un consilier de probațiune din cadrul serviciului de probațiune competent potrivit legii în circumscripția căruia se află penitenciarul. Secretariatul comisiei se asigură de către șeful serviciului evidență din penitenciarul respectiv.","(3) Comisia formulează propuneri de liberare condiționată a persoanei condamnate, ținând seama de:a) fracțiunea din pedeapsă efectiv executată și de partea din durata pedepsei care este considerată ca executată, conform art. 96; ... b) regimul de executare a pedepsei privative de libertate în care este repartizată; ... c) îndeplinirea obligațiilor civile stabilite prin hotărârea de condamnare, în afară de cazul când dovedește că nu a avut nicio posibilitate să le îndeplinească; ... d) conduita persoanei condamnate și eforturile acesteia pentru reintegrare socială, în special în cadrul muncii prestate, al activităților educative, moral-religioase, culturale, terapeutice, de consiliere psihologică și asistență socială, al instruirii școlare și al formării profesionale, precum și responsabilitățile încredințate, recompensele acordate și sancțiunile disciplinare aplicate; ... e) antecedentele sale penale. ...","(4) În activitatea sa, comisia ține cont și de rezultatele aplicării instrumentelor-standard de evaluare a activităților desfășurate de deținuți, aprobate prin decizie a directorului general al Administrației Naționale a Penitenciarelor.","(5) Persoana condamnată este adusă în fața comisiei pentru liberare condiționată, cu excepția situațiilor în care prezintă afecțiuni medicale confirmate de medic, care nu permit prezentarea sa. În acest caz, persoana condamnată poate depune înscrisuri.","(6) Propunerea comisiei pentru liberare condiționată este cuprinsă într-un proces-verbal motivat, care cuprinde poziția membrilor comisiei față de propunerea de liberare.","(7) La procesul-verbal de propunere a liberării condiționate se anexează, prin grija consilierului de probațiune din cadrul serviciului de probațiune competent potrivit legii în circumscripția căruia se află penitenciarul, recomandările cu privire la măsurile de supraveghere și obligațiile prevăzute la art. 101 din Codul penal care pot fi aplicate de către instanța de judecată, în cazul în care restul de pedeapsă rămas neexecutat la data liberării persoanei condamnate este de 2 ani sau mai mare.","(8) Dispozițiile alin. (7) nu se aplică persoanelor condamnate de cetățenie străină, față de care s-a dispus pedeapsa complementară prevăzută la art. 66 alin. (1) lit. c) din Codul penal.","(9) Persoana condamnată poate prezenta, în fața comisiei pentru liberare condiționată, dovezi că și-a îndeplinit obligațiile civile stabilite prin hotărârea de condamnare ori s-a aflat în imposibilitatea îndeplinirii acestor obligații.","(10) Procesul-verbal prevăzut la alin. (6), împreună cu documentele care atestă mențiunile cuprinse în acesta, se înaintează judecătoriei în a cărei circumscripție se află penitenciarul, iar procesul-verbal se comunică de îndată persoanei condamnate.","(11) În cazul în care comisia pentru liberare condiționată constată că persoana condamnată nu întrunește condițiile pentru a fi liberată condiționat, în procesul-verbal întocmit potrivit alin. (6) fixează un termen pentru reexaminarea situației acesteia, care nu poate fi mai mare de un an. În cazul în care cererea de liberare condiționată este formulată înainte de îndeplinirea condiției privind îndeplinirea fracțiunii prevăzute de Codul penal, iar perioada rămasă de executat până la împlinirea acestei fracțiuni este mai mare de un an, termenul stabilit de comisie va fi data împlinirii fracțiunii prevăzute de Codul penal. În cazul în care perioada rămasă de executat până la împlinirea acestei fracțiuni este mai mică de un an, termenul fixat de comisie poate depăși data împlinirii fracțiunii prevăzute de Codul penal, dar nu poate fi mai mare de un an. Totodată, comisia comunică, de îndată, procesul-verbal persoanei condamnate, care are posibilitatea ca, în termen de 3 zile de la aducerea la cunoștință, sub semnătură, să se adreseze, cu cerere de liberare condiționată, judecătoriei în circumscripția căreia se află penitenciarul.","(12) Metodologia de lucru a comisiei pentru liberare condiționată este stabilită prin regulamentul de aplicare a prezentei legi.","(13) În vederea soluționării cererii de liberare condiționată a persoanei condamnate sau a propunerii formulate de comisie, instanța poate consulta dosarul individual al persoanei condamnate sau poate solicita copii ale actelor și documentelor din acesta."],"number":"Art. 97"},{"heading":"Transferarea persoanelor arestate preventiv în penitenciar","id":"l254-115","intro":"(1) După trimiterea în judecată, persoanele arestate preventiv sunt transferate în penitenciar.","items":["(2) Persoanele arestate preventiv aflate în curs de judecată care au fost selecționate pentru a presta activități în interesul centrului pot fi menținute, cu acordul lor, pe o perioadă de maximum 6 luni, în centrul de reținere și arestare preventivă.","(3) Persoanele arestate preventiv aflate în cursul urmăririi penale pot fi transferate, temporar, în penitenciarele-spital, dacă se află într-una dintre următoarele situații:a) organul de urmărire penală a dispus efectuarea unei expertize medico-legale psihiatrice; ... b) suferă de o afecțiune medicală care necesită internare și poate fi tratată în rețeaua sanitară a Administrației Naționale a Penitenciarelor. ...","(4) În situația prevăzută la alin. (3) lit. b), transferarea temporară se face cu aprobarea directorului penitenciarului-spital, ținând seama și de gradul de ocupare a penitenciarului-spital.","(5) Dacă, pe parcursul internării în penitenciarul-spital, se impune internarea persoanei arestate preventiv aflate în curs de urmărire penală într-un spital din rețeaua sanitară publică, organele de poliție din cadrul structurii teritoriale pe raza căreia se află unitatea medicală asigură paza și supravegherea persoanei private de libertate.","(6) Transferul persoanelor arestate preventiv în condițiile prezentului articol se dispune de către șeful centrului de reținere și arestare preventivă."],"number":"Art. 115"},{"heading":"Centrele de arestare preventivă","id":"l254-120","intro":"(1) În cursul judecății, arestarea preventivă se execută în secțiile speciale de arestare preventivă din penitenciare sau în centrele de arestare preventivă de pe lângă penitenciare, care se organizează și funcționează în subordinea Administrației Naționale a Penitenciarelor.","items":["(2) În secțiile speciale de arestare preventivă din penitenciare sunt deținute și persoanele condamnate care sunt cercetate în stare de arest preventiv în altă cauză.","(3) Persoanelor prevăzute la alin. (2) li se aplică prevederile titlului I, precum și cele ale cap. II din titlul III, referitor la siguranța penitenciarelor.","(4) Centrele de arestare preventivă se înființează prin hotărâre a Guvernului.","(5) Prin ordin al ministrului justiției se stabilesc penitenciarele în a căror circumscripție funcționează centrele de arestare preventivă, precum și regulamentul de organizare și funcționare a acestora.","(6) Măsurile necesare pentru siguranța centrelor de arestare preventivă se stabilesc prin regulamentul prevăzut la art. 15 alin. (3)."],"number":"Art. 120"},{"heading":"Executarea arestării preventive în cursul judecății","id":"l254-121","intro":"(1) Primirea în centrele de arestare preventivă sau în penitenciare a persoanelor arestate preventiv în curs de judecată se face pe baza mandatului de arestare prevăzut la art. 2 alin. (4), după stabilirea identității acestora.","items":["(2) Centrele de arestare preventivă și secțiile speciale de arestare preventivă din penitenciare sunt obligate să asigure exercitarea drepturilor prevăzute în Codul de procedură penală.","(3) Dispozițiile art. 110 alin. (1) se aplică în mod corespunzător, cu excepția lit. a)."],"number":"Art. 121"},{"heading":"Regimul arestaților preventiv","id":"l254-122","intro":"(1) Persoanele arestate preventiv sunt cazate, de regulă, în comun, pot desfășura activități educative, moral-religioase, culturale, terapeutice, de consiliere psihologică și asistență socială, instruire școlară și formare profesională, în grupuri, în interiorul centrului de arestare preventivă sau al penitenciarului, sub pază și supraveghere, în condițiile stabilite prin regulamentul de aplicare a prezentei legi.","items":["(2) Persoanele arestate preventiv pot presta, la cererea lor, o muncă în interiorul sau exteriorul centrului de arestare preventivă sau al penitenciarului, sub pază și supraveghere continuă, cu aprobarea directorului.","(3) Dispozițiile art. 34 alin. (2) se aplică în mod corespunzător și persoanelor arestate preventiv în curs de judecată."],"number":"Art. 122"},{"heading":"Regimul arestaților minori","id":"l254-123","intro":"(1) În cursul judecății, minorii arestați preventiv execută măsura preventivă în centre de detenție sau în centre de arestare preventivă.","items":["(2) Pentru prezentarea în fața organelor judiciare, minorii arestați preventiv pot fi transferați în secțiile speciale de arestare preventivă din penitenciare pentru o perioadă de maximum 10 zile, fiind cazați separat de majori.","(3) În intervalul prevăzut la alin. (2), minorii execută măsura arestării preventive cu respectarea particularităților vârstei, cu asigurarea asistenței psihosociale necesare, pentru a nu fi prejudiciată dezvoltarea lor fizică, psihică sau morală.","(4) La împlinirea vârstei de 18 ani, minorul arestat rămâne sau este transferat în centrul de detenție.","(5) Dispozițiile art. 117 se aplică în mod corespunzător, cu excepția alin. (4) lit. a) și g).","(6) Minorii arestați preventiv prestează muncă numai la cererea lor, dispozițiile art. 163 aplicându-se în mod corespunzător."],"number":"Art. 123"},{"heading":"Scopul executării măsurilor educative privative de libertate","id":"l254-135","intro":"(1) Prin executarea măsurilor educative privative de libertate se urmărește reintegrarea în societate a persoanelor internate și responsabilizarea acestora, în vederea asumării propriilor acțiuni și a prevenirii săvârșirii de noi infracțiuni.","items":["(2) Măsurile educative privative de libertate sunt puse în executare în condiții care să nu îngrădească exercitarea dreptului la viață privată mai mult decât este inerent executării acestora."],"number":"Art. 135"},{"heading":"Locul de executare","id":"l254-136","intro":"Măsurile educative privative de libertate pot fi executate:a) într-un centru educativ; ... b) într-un centru de detenție. ...","items":[],"number":"Art. 136"},{"heading":"Consiliul educativ","id":"l254-145","intro":"(1) În fiecare centru educativ se constituie un consiliu educativ, al cărui scop este individualizarea regimului de executare a măsurii educative a internării într-un centru educativ, prin stabilirea asistenței educaționale, psihologice și sociale acordate fiecărei persoane internate.","items":["(2) Consiliul educativ este alcătuit din directorul centrului, care este și președintele consiliului, directorul adjunct pentru educație și asistență psihosocială, educatorul responsabil de caz, învățătorul sau dirigintele, un psiholog, un asistent social și șeful serviciului supraveghere, evidență și acordare drepturi persoane internate.","(3) La lucrările consiliului educativ pot participa, în calitate de invitați, în cazul minorilor, un consilier de probațiune din cadrul serviciului de probațiune competent potrivit legii în circumscripția căruia se află centrul educativ și un reprezentant al direcției generale de asistență socială și protecția copilului din subordinea consiliului județean, respectiv a consiliului local al sectorului municipiului București pe teritoriul căruia se află centrul educativ.","(4) Secretariatul consiliului educativ este asigurat de către o persoană din cadrul serviciului educativ, alta decât educatorul responsabil de caz."],"number":"Art. 145"},{"heading":"Comisia pentru stabilirea, individualizarea și schimbarea regimului de executare a măsurii educative a internării în centrul de detenție","id":"l254-146","intro":"(1) În fiecare centru de detenție se constituie o comisie pentru stabilirea, individualizarea și schimbarea regimului de executare a măsurii internării, alcătuită din directorul centrului, care este și președintele comisiei, directorul adjunct pentru educație și asistență psihosocială, directorul adjunct pentru siguranța deținerii, medicul-șef, educatorul responsabil de caz, un psiholog și un asistent social.","items":["(2) La lucrările comisiei prevăzute la alin. (1) pot participa, în calitate de invitați, în cazul minorilor, un consilier de probațiune din cadrul serviciului de probațiune competent potrivit legii în circumscripția căruia se află centrul de detenție și un reprezentant al direcției generale de asistență socială și protecția copilului din subordinea consiliului județean, respectiv a consiliului local al sectorului municipiului București pe teritoriul căruia se află centrul de detenție.","(3) Prevederile art. 145 alin. (4) se aplică în mod corespunzător."],"number":"Art. 146"},{"heading":"Tipurile regimurilor de executare a măsurii internării într-un centru de detenție","id":"l254-147","intro":"(1) Regimurile de executare a măsurii educative a internării într-un centru de detenție sunt:a) regimul închis; ... b) regimul deschis. ...","items":["(2) Regimurile de executare a măsurii educative a internării într-un centru de detenție se diferențiază în raport cu gradul de limitare a libertății de mișcare a persoanei internate, precum și cu modul și locul de organizare și desfășurare a activităților."],"number":"Art. 147"},{"heading":"Aplicarea provizorie a regimului de executare","id":"l254-148","intro":"(1) După terminarea perioadei de carantină și observare, fiecărei persoane internate căreia nu i s-a stabilit regimul de executare i se aplică provizoriu regimul de executare corespunzător cuantumului măsurii educative pe care o execută, potrivit art. 149 alin. (1) și art. 150 alin. (1).","items":["(2) Dispozițiile art. 33 se aplică în mod corespunzător."],"number":"Art. 148"},{"heading":"Stabilirea regimului de executare a măsurii educative a internării într-un centru de detenție","id":"l254-152","intro":"(1) Comisia prevăzută la art. 146 stabilește regimul de executare a măsurii educative a internării în centrul de detenție, dispozițiile art. 39 aplicându-se în mod corespunzător.","items":["(2) La stabilirea regimului de executare se ține seama dacă măsura educativă se execută ca urmare a revenirii de către instanță asupra înlocuirii sau liberării din centrul educativ, potrivit dispozițiilor art. 125 alin. (6) din Codul penal."],"number":"Art. 152"},{"heading":"Schimbarea regimului de executare a măsurii educative a internării într-un centru de detenție","id":"l254-153","intro":"(1) Comisia prevăzută la art. 146 are obligația să analizeze, după executarea unei pătrimi din durata măsurii educative, conduita persoanei internate și eforturile depuse în vederea reintegrării sociale. În cazul în care comisia apreciază că se impune schimbarea regimului de executare, dispune, în acest sens, prin hotărâre.","items":["(2) Schimbarea regimului de executare din regimul închis în regimul deschis se poate dispune dacă persoana internată a avut o bună conduită, a dovedit interes constant în cadrul activităților de instruire școlară și formare profesională, precum și în cadrul altor programe desfășurate în centru și a făcut progrese evidente în vederea reintegrării sociale.","(3) În activitatea sa, comisia ține cont și de rezultatele aplicării instrumentelor-standard de evaluare a activităților desfășurate de persoanele internate, aprobate prin decizie a directorului general al Administrației Naționale a Penitenciarelor.","(4) Schimbarea regimului de executare din regimul deschis în regimul închis se poate dispune în orice moment al executării măsurii internării în centrul de detenție, dacă persoana internată a fost sancționată disciplinar pentru o abatere disciplinară foarte gravă sau pentru abateri disciplinare grave repetate.","(5) Împrejurările prevăzute la alin. (2) sau (3) sunt constatate printr-un raport care este adus la cunoștința persoanei internate sub semnătură.","(6) Hotărârea comisiei prevăzute la art. 146, prin care se dispune menținerea sau schimbarea regimului de executare, cuprinde și termenul de reanalizare, care nu poate fi mai mare de 6 luni.","(7) Comisia prevăzută la art. 146 are obligația de a analiza, periodic, situația persoanei condamnate la împlinirea termenului stabilit conform alin. (6).","(8) Împotriva deciziei comisiei privind schimbarea regimului de executare, persoana internată poate formula plângere, care este soluționată potrivit dispozițiilor art. 40 alin. (11)-(22), care se aplică în mod corespunzător."],"number":"Art. 153"},{"heading":"Primirea persoanei într-un centru educativ sau într-un centru de detenție","id":"l254-156","intro":"(1) Primirea persoanelor internate într-un centru educativ sau într-un centru de detenție se face în baza hotărârii judecătorești rămase definitivă, după stabilirea identității acestora, dispozițiile art. 43 aplicându-se în mod corespunzător.","items":["(2) În termen de 3 zile de la primirea persoanei internate în centru, directorul centrului ia măsuri pentru informarea în scris a familiei sau a reprezentantului legal, cu privire la posibilitățile vizitării și la modalitățile de sprijinire a procesului de reintegrare socială desfășurat în centru."],"number":"Art. 156"},{"heading":"Transferarea persoanei internate","id":"l254-158","intro":"(1) Transferarea persoanei internate în alt centru, pentru motive întemeiate, se dispune la propunerea consiliului educativ sau a comisiei prevăzute la art. 146 sau la cererea persoanei internate, a familiei ori a reprezentantului legal al acesteia, cu avizul consiliului educativ ori al comisiei prevăzute la art. 146, de către directorul general al Administrației Naționale a Penitenciarelor.","items":["(2) Dispozițiile art. 43 alin. (4) se aplică în mod corespunzător.","(3) În cazul în care se decide transferarea persoanei internate într-un alt centru sau într-un centru de reținere și arestare preventivă sau de arestare preventivă, soluționarea contestațiilor prevăzute de prezentul titlu, formulate de persoana ce urmează a fi transferată până la data dispoziției de transfer, se face, de urgență, de către judecătorul de supraveghere a privării de libertate de la centrul de la care s-a dispus transferul, înainte de realizarea efectivă a transferului."],"number":"Art. 158"},{"heading":"Punerea în libertate","id":"l254-160","intro":"Punerea în libertate a minorului din centrul educativ sau centrul de detenție se comunică familiei sau reprezentantului legal al acestuia.","items":[],"number":"Art. 160"},{"heading":"Condițiile și procedura de înlocuire a măsurii internării în centrul de detenție sau în centrul educativ cu măsura educativă a asistării zilnice","id":"l254-179","intro":"(1) Înainte de împlinirea vârstei de 18 ani, persoanelor internate li se poate înlocui măsura internării în centrul de detenție sau în centrul educativ cu măsura educativă a asistării zilnice, dacă îndeplinesc condițiile prevăzute la art. 124 alin. (4) și, respectiv, art. 125 alin. (4) din Codul penal.","items":["(2) Consiliul educativ sau comisia prevăzută la art. 146, cu participarea judecătorului de supraveghere a privării de libertate, în calitate de președinte, și a unui consilier de probațiune din cadrul serviciului de probațiune competent potrivit legii în circumscripția căruia se află centrul, stabilește dacă minorul a dovedit interes constant pentru însușirea cunoștințelor școlare și profesionale și a făcut progrese în vederea reintegrării sociale, în prezența acestuia, și formulează propunerea de înlocuire a internării cu măsura educativă a asistării zilnice. La formularea propunerii se ține seama și de perioadele de internare anterioare.","(3) La analiza situației minorului, consiliul educativ sau comisia prevăzută la art. 146, în componența prevăzută la alin. (2), poate lua în considerare implicarea acestuia în muncă.","(4) Propunerea formulată conform alin. (2), cuprinsă într-un proces-verbal motivat, împreună cu documentele care atestă mențiunile consemnate în acesta, se înaintează instanței competente potrivit art. 516 alin. (2) și art. 517 alin. (2) din Codul de procedură penală.","(5) Dispozițiile art. 97 alin. (4)-(8) și alin. (10)-(13) se aplică în mod corespunzător. Termenul pe care îl fixează consiliul educativ sau comisia prevăzută la art. 146, în componența prevăzută la alin. (2), în cazul în care constată că persoana internată nu îndeplinește condițiile pentru înlocuirea măsurii internării în centrul de detenție sau în centrul educativ cu măsura educativă a asistării zilnice, nu poate fi mai mare de 4 luni."],"number":"Art. 179"},{"heading":"Condițiile și procedura de acordare a liberării din centrul educativ sau de detenție","id":"l254-180","intro":"(1) După împlinirea vârstei de 18 ani, persoanele internate pot fi liberate dacă îndeplinesc condițiile prevăzute la art. 124 alin. (4) și, respectiv, art. 125 alin. (4) din Codul penal.","items":["(2) În prezența persoanei internate, consiliul educativ sau comisia prevăzută la art. 146, cu participarea judecătorului de supraveghere a privării de libertate, în calitate de președinte, și a unui consilier de probațiune din cadrul serviciului de probațiune competent potrivit legii în circumscripția căruia se află centrul, stabilește dacă aceasta a dovedit interes constant pentru însușirea cunoștințelor școlare și profesionale și a făcut progrese în vederea reintegrării sociale și formulează propunerea de liberare din centrul educativ sau de detenție. La formularea propunerii se ține seama și de perioadele de internare anterioare.","(3) La analiza situației persoanei internate, consiliul educativ sau comisia prevăzută la art. 146, în componența prevăzută la alin. (2), poate lua în considerare implicarea în muncă.","(4) Propunerea formulată conform alin. (2), cuprinsă într-un proces-verbal motivat, care cuprinde poziția membrilor comisiei față de propunerea de liberare, împreună cu documentele care atestă mențiunile consemnate în acesta, se înaintează instanței competente potrivit art. 516 alin. (2) și art. 517 alin. (2) din Codul de procedură penală.","(5) Dispozițiile art. 97 alin. (4)-(8) și (10)-(13) se aplică în mod corespunzător. Termenul pe care îl fixează consiliul educativ sau comisia prevăzută la art. 146, în componența prevăzută la alin. (2), în cazul în care constată că persoana internată nu îndeplinește condițiile pentru liberarea din centrul educativ sau de detenție, nu poate fi mai mare de 6 luni."],"number":"Art. 180"},{"heading":"Dispoziții comune","id":"l254-181","intro":"(1) Înlocuirea măsurii internării în centrul educativ sau de detenție cu măsura educativă a asistării zilnice și liberarea se dispun de către instanța din circumscripția teritorială în care se află centrul, corespunzătoare în grad instanței de executare, la cererea persoanei internate sau la propunerea făcută potrivit art. 179 și 180.","items":["(2) Când instanța constată că nu sunt îndeplinite condițiile pentru înlocuirea măsurii internării în centrul educativ sau de detenție cu măsura educativă a asistării zilnice sau a liberării, prin hotărârea de respingere, fixează termenul după expirarea căruia propunerea sau cererea va putea fi reînnoită. Termenul nu poate fi mai mare decât cel stabilit potrivit art. 179 alin. (5) și art. 180 alin. (5).","(3) Hotărârea instanței poate fi atacată cu contestație la instanța din circumscripția teritorială în care se află centrul, corespunzătoare în grad instanței care a avut competența să judece apelul hotărârii prin care s-a aplicat măsura educativă, în termen de 3 zile de la comunicare. Contestația formulată de procuror este suspensivă de executare.","(4) O copie de pe hotărârea rămasă definitivă prin care s-a dispus înlocuirea măsurii sau liberarea din centrul educativ sau de detenție se comunică serviciului de probațiune și organelor de poliție competente."],"number":"Art. 181"},{"heading":"Condițiile și procedura pentru continuarea executării măsurii educative privative de libertate în penitenciar","id":"l254-182","intro":"(1) Dacă în cursul executării unei măsuri educative privative de libertate persoana internată, care a împlinit vârsta de 18 ani, are un comportament prin care influențează negativ sau împiedică procesul de recuperare și reintegrare a celorlalte persoane internate, administrația centrului poate cere instanței stabilite, potrivit art. 181, continuarea executării măsurii educative într-un penitenciar.","items":["(2) Prin comportament care influențează negativ sau împiedică procesul de recuperare și reintegrare a celorlalte persoane internate se înțelege:a) inițierea de acțiuni care conduc la nefrecventarea sau refuzul său constant, precum și al altor persoane internate de a participa la cursuri de instruire școlară și formare profesională, la programe de educație, asistență psihologică și asistență socială; ... b) introducerea, deținerea sau traficul de arme, materiale explozive, droguri, substanțe toxice sau alte obiecte și substanțe care pun în pericol siguranța centrului, a misiunilor sau a persoanelor; ... c) nerespectarea interdicțiilor prevăzute la art. 82 lit. a)-c); ... d) nerespectarea, în mod repetat, a interdicțiilor prevăzute la art. 82 lit. f) și h). ...","(3) Consiliul educativ sau comisia prevăzută la art. 146, cu participarea judecătorului de supraveghere a privării de libertate, în calitate de președinte, și a asistentului social, din oficiu sau la sesizarea comisiei de disciplină, analizează situația persoanei internate care a săvârșit una dintre faptele prevăzute la alin. (2), în prezența acesteia, și poate propune continuarea executării măsurii educative privative de libertate în penitenciar.","(4) Propunerea motivată de continuare a executării măsurii educative privative de libertate în penitenciar este cuprinsă într-un proces-verbal. Procesul-verbal, împreună cu documentele care atestă mențiunile consemnate în acesta, se înaintează instanței competente potrivit art. 518 din Codul de procedură penală, după ce acesta a fost comunicat persoanei internate.","(5) Dispozițiile art. 97 alin. (12) și (13) se aplică în mod corespunzător.","(6) Hotărârea instanței este definitivă."],"number":"Art. 182"}]},
  {id:"hg157",title:"HG nr. 157/2016 — Regulament",scope:"Titlul III: art. 50–52, 54, 65, 74, 81, 88–93, 97, 108, 116, 127, 169 și cap. VIII (art. 204–207); Titlul V: art. 301, 304 și cap. X (art. 337–340)",url:"https://legislatie.just.ro/Public/DetaliiDocument/269789",status:"integrat",articles:[
    {"heading":"Regimul aplicabil deținuților arestați preventiv în altă cauză","id":"hg157-50","intro":"(1) Regimul de executare stabilit pentru deținuții condamnați și arestați preventiv în altă cauză se suspendă până la revocarea, înlocuirea sau încetarea arestului preventiv. În perioada de suspendare se aplică regimul specific arestaților preventiv. Repartizarea în cadrul secției de arestare preventivă se realizează prin decizie a directorului penitenciarului.","items":["(2) În cazul persoanelor prevăzute la alin. (1) se aplică în mod corespunzător dispozițiile art. 91 și art. 204-206.","(3) În perioada arestului preventiv, deținuților repartizați în regim de maximă siguranță, clasificați în categoria celor care prezintă risc pentru siguranța penitenciarului și cărora li s-a suspendat regimul de executare, li se aplică aceleași măsuri de siguranță până la încetarea motivelor care au determinat luarea acestora."],"number":"Art. 50"},
    {"heading":"Aplicarea provizorie a regimului de executare","id":"hg157-51","intro":"(1) Regimul provizoriu se aplică până la prima întrunire a comisiei prevăzute la art. 32 din Lege:a) de la data expirării perioadei de carantină și observare, pentru deținuții care au fost primiți în penitenciar în baza mandatului de executare a pedepsei privative de libertate și pentru deținuții cărora le-a fost emis mandatul de executare a pedepsei privative de libertate în acest interval de timp; ... b) de la data încetării măsurii arestării preventive ca urmare a intervenirii hotărârii definitive de condamnare în cauza respectivă; ... c) de la data înlocuirii, încetării de drept sau revocării măsurii arestării preventive pentru deținuții arestați în altă cauză, dacă acestora nu li s-a stabilit un regim de executare. ...","items":["(2) Aplicarea regimului provizoriu se face în baza deciziei directorului penitenciarului, care este executorie și definitivă."],"number":"Art. 51"},
    {"heading":"Măsuri specifice pentru perioada aplicării regimului provizoriu","id":"hg157-52","intro":"(1) Pe toată perioada aplicării regimului provizoriu deținutul beneficiază de drepturile pe care le au deținuții incluși definitiv în respectivul regim de executare, cu excepția dreptului la muncă.","items":["(2) Cazarea deținuților cărora li se aplică regimul de executare provizoriu se realizează în cadrul secțiilor de deținere aferente regimului de executare respectiv."],"number":"Art. 52"},
    {"heading":"Categoriile de deținuți cărora li se aplică regimul de maximă siguranță","id":"hg157-54","intro":"(1) Regimul de maximă siguranță se aplică inițial, în conformitate cu prevederile art. 34 alin. (1) din Lege, persoanelor condamnate la pedeapsa detențiunii pe viață și persoanelor condamnate la pedeapsa închisorii mai mare de 13 ani, precum și celor care prezintă risc pentru siguranța penitenciarului, în condițiile art. 27 și 28.","items":["(2) Regimul de maximă siguranță se aplică deținuților, clasificați inițial în alt regim de executare, care au comis o infracțiune sau o abatere disciplinară foarte gravă și care, prin conduita lor, afectează în mod grav desfășurarea normală a activităților în locul de deținere ori siguranța acestuia.","(3) Regimul de maximă siguranță se aplică deținuților condamnați la pedeapsa închisorii mai mare de 3 ani, dar care nu depășește 13 ani, în următoarele situații:a) au săvârșit abateri disciplinare repetate; ... b) constituie pericol pentru ei înșiși, pentru alți deținuți, pentru personal sau pentru societate, având în vedere antecedentele privind actele de indisciplină, de intimidare, de violență, de distrugere. ..."],"number":"Art. 54"},
    {"heading":"Categoriile de deținuți cărora li se aplică regimul închis","id":"hg157-65","intro":"(1) Regimul închis se aplică inițial deținuților condamnați la pedeapsa închisorii mai mare de 3 ani, dar care nu depășește 13 ani, în conformitate cu prevederile art. 36 alin. (1) din Lege.","items":["(2) Regimul închis se aplică și:a) deținuților clasificați inițial în regim semideschis sau deschis care au comis o abatere disciplinară foarte gravă sau abateri disciplinare grave, în mod repetat, și care, prin conduita lor, afectează desfășurarea normală a activităților în locul de deținere; ... b) deținuților clasificați inițial în regimul de maximă siguranță care au avut o bună conduită și au făcut eforturi pentru reintegrare socială; ... c) deținuților care au împlinit vârsta de 65 de ani, femeilor însărcinate sau care au în îngrijire un copil în vârstă de până la un an, persoanelor încadrate în gradul I de invaliditate, precum și celor cu afecțiuni locomotorii grave, dacă acestea au fost condamnate la pedeapsa închisorii mai mare de 13 ani, în conformitate cu dispozițiile art. 35 din Lege; ... d) în mod excepțional, deținuților condamnați la pedeapsa închisorii mai mare de 13 ani, dacă în urma analizării naturii, modului de săvârșire a infracțiunii și a persoanei acestora, se apreciază că nu este oportună repartizarea în regimul de maximă siguranță, potrivit art. 34 alin. (3) din Lege. La această apreciere, în baza aplicării instrumentelor-standard de evaluare a activităților desfășurate de deținuți, pot fi luate în considerare aspecte privind vârsta și starea de sănătate, lipsa antecedentelor penale, comportamentul pe parcursul procesului penal, perioada executată până la momentul stabilirii regimului de executare, participarea la activități pe durata executării măsurii arestării preventive și comportamentul în această perioadă; ... e) în mod excepțional, deținuților condamnați la pedeapsa închisorii mai mare de un an, dar care nu depășește 3 ani, în considerarea naturii, modului de săvârșire a infracțiunii și a persoanei acestora, în conformitate cu dispozițiile art. 37 alin. (2) din Lege. Dispozițiile art. 54 alin. (3) se aplică în mod corespunzător. ..."],"number":"Art. 65"},
    {"heading":"Categoriile de deținuți cărora li se aplică regimul semideschis","id":"hg157-74","intro":"(1) Regimul semideschis se aplică deținuților condamnați la pedeapsa închisorii mai mare de un an, dar care nu depășește 3 ani, în conformitate cu prevederile art. 37 alin. (1) din Lege.","items":["(2) Regimul semideschis se aplică și:a) deținuților clasificați inițial în regim deschis care au comis o abatere disciplinară gravă sau abateri disciplinare grave, în mod repetat, și care din cauza conduitei necorespunzătoare au devenit incompatibile cu acest tip de regim; ... b) deținuților clasificați inițial în regimul închis care au avut o bună conduită și au făcut eforturi temeinice pentru reintegrare socială; ... c) în mod excepțional, deținuților condamnați la pedeapsa închisorii mai mare de 3 ani, dar care nu depășește 13 ani, în considerarea naturii, modului de săvârșire a infracțiunii și a persoanei acestora, potrivit art. 36 alin. (2) din Lege. Dispozițiile art. 65 alin. (2) lit. d) se aplică în mod corespunzător; ... d) în mod excepțional, deținuților condamnați la pedeapsa închisorii mai mică de un an, în conformitate cu art. 38 alin. (2) din Lege. Dispozițiile art. 54 alin. (3) se aplică în mod corespunzător. ..."],"number":"Art. 74"},
    {"heading":"Categoriile de deținuți cărora li se aplică regimul deschis","id":"hg157-81","intro":"(1) Regimul deschis se aplică deținuților condamnați la pedeapsa închisorii de cel mult un an, în conformitate cu prevederile art. 38 alin. (1) din Lege.","items":["(2) Regimul deschis se aplică și:a) deținuților clasificați inițial în regimul semideschis care au avut o bună conduită și au făcut eforturi serioase pentru reintegrare socială; ... b) în mod excepțional, deținuților condamnați la pedeapsa închisorii mai mare de un an, dar care nu depășește 3 ani, în considerarea naturii, modului de săvârșire a infracțiunii și a persoanei acestora, în conformitate cu art. 37 alin. (2) din Lege. Dispozițiile art. 65 alin. (2) lit. c) se aplică în mod corespunzător. ...","(3) Regimul deschis se bazează pe disciplina liber consimțită, pe sentimentul de responsabilitate față de comunitatea din care provin deținuții și îi încurajează să folosească cu bună-credință libertățile ce le sunt conferite."],"number":"Art. 81"},
    {"heading":"Procedura stabilirii regimului de executare","id":"hg157-88","intro":"(1) Cu ocazia stabilirii regimului de executare a deținuților, membrii comisiei prevăzute de art. 32 din Lege țin cont și de rezultatele aplicării instrumentelor-standard de evaluare a activităților desfășurate de deținuți, prevăzute la art. 40 alin. (4) din Lege, și au în vedere:a) durata pedepsei privative de libertate și perioada executată până la momentul stabilirii regimului de executare; ... b) gradul de risc al deținutului, natura și modul de săvârșire a infracțiunii, persoana acestuia; ... c) antecedentele penale; ... d) vârsta și starea de sănătate; ... e) conduita, pozitivă sau negativă, inclusiv în perioadele de detenție anterioare; ... f) nevoile identificate și abilitățile necesare includerii în programe educative, de asistență psihologică și asistență socială; ... g) disponibilitatea de a presta muncă și de a participa la activități educative, culturale, terapeutice, de consiliere psihologică și asistență socială, moral-religioase, instruire școlară și formare profesională. ...","items":["(2) În raport cu prevederile alin. (1) și ale art. 39 din Lege, fiecare membru al comisiei propune motivat regimul de executare.","(3) Dacă, după aplicarea criteriilor prevăzute la alin. (1), comisia nu identifică situația de excepție prevăzută la art. 54 alin. (3), art. 65 alin. (2) lit. d) și e), art. 74 alin. (2) lit. c) și d) și art. 81 alin. (2) lit. b), va ține seama strict de cuantumul pedepsei privative de libertate, prevăzut de Lege, pentru stabilirea regimului de executare.","(4) În cazul în care deținutul este condamnat la mai multe pedepse privative de libertate, la stabilirea regimului de executare se are în vedere pedeapsa cea mai mare.","(5) Stabilirea regimului se face prin votul deschis al membrilor comisiei, hotărârea fiind luată cu majoritate simplă.","(6) Propunerile membrilor comisiei, motivațiile și decizia finală a comisiei, pentru fiecare caz în parte, se consemnează într-un proces-verbal, datat și înregistrat, care se depune la dosarul individual. Dacă stabilirea regimului se efectuează după terminarea perioadei de carantină și observare sau după aplicarea regimului provizoriu, prevăzute de art. 39 din Lege, comisia prevede un termen de reanalizare, în condițiile art. 40 alin. (8) din Lege.","(7) Decizia membrilor comisiei, întocmită în două exemplare, care cuprinde menționarea căii de atac existente și a termenului de exercitare a acesteia, se aduce la cunoștința deținutului. Un exemplar se înmânează deținutului, iar celălalt, din care să rezulte luarea la cunoștință, se depune la dosarul individual.","(8) Deținutul poate fi ascultat de membrii comisiei, pentru lămurirea unor aspecte ce țin de persoana acestuia.","(9) Documentele create în procedura stabilirii regimului de executare se depun în dosarul individual.","(10) Mențiuni despre stabilirea regimului de executare se fac în dosarul individual, în aplicațiile informatizate și în celelalte documente operative stabilite prin regulamentul prevăzut de art. 15 alin. (3) din Lege."],"number":"Art. 88"},
    {"heading":"Sesizarea judecătorului de supraveghere a privării de libertate","id":"hg157-89","intro":"(1) Deținutul nemulțumit de regimul de executare stabilit de comisia prevăzută de art. 32 din Lege poate formula, în scris, plângere la judecătorul de supraveghere a privării de libertate, în termen de 3 zile de la data când a luat cunoștință de regimul de executare a pedepsei stabilit, în conformitate cu prevederile art. 39 alin. (3) din Lege.","items":["(2) În cazul în care comisia apreciază că deținutul prezintă risc pentru siguranța penitenciarului, decizia prin care s-a stabilit regimul de executare însoțește procesul-verbal de stabilire a riscului.","(3) Plângerea se depune la judecătorul de supraveghere a privării de libertate prin grija serviciului sau biroului evidență."],"number":"Art. 89"},
    {"heading":"Punerea în aplicare a hotărârii de stabilire a regimului de executare","id":"hg157-90","intro":"Decizia de stabilire a regimului de executare, încheierea judecătorului de supraveghere a privării de libertate sau, după caz, sentința instanței de judecată se pune în aplicare la data înregistrării în penitenciar, de către personalul desemnat prin act administrativ emis de directorul locului de deținere.","items":[],"number":"Art. 90"},
    {"heading":"Schimbarea regimului de executare","id":"hg157-91","intro":"(1) Schimbarea regimului de executare a pedepsei privative de libertate se realizează în conformitate cu dispozițiile art. 40 din Lege.","items":["(2) Pe baza raportului întocmit de către comisia prevăzută la art. 32 din Lege se ia hotărârea prin care se dispune menținerea sau schimbarea regimului de executare, în situația în care:a) sunt executate fracțiunile din pedeapsă prevăzute la art. 40 alin. (2) din Lege; ... b) a intervenit o nouă condamnare la o pedeapsă privativă de libertate; ... c) este sesizată de comisia de disciplină în cazul comiterii unei abateri foarte grave sau, în mod repetat, a unor abateri grave; ... d) deținutul a comis o infracțiune; ... e) la apariția sau încetarea cauzelor prevăzute la art. 35 alin. (1) din Lege; ... f) la împlinirea termenului prevăzut de art. 40 alin. (8) Lege. ... g) la reevaluarea persoanelor incluse în categoria celor care prezintă risc pentru siguranța penitenciarului, dacă au fost executate fracțiunile din pedeapsă prevăzute la art. 40 alin. (2) din Lege. ...","(3) Hotărârea comisiei, de menținere sau de schimbare a regimului de executare, întocmită în două exemplare, care cuprinde menționarea căii de atac existente și a termenului de exercitare a acesteia, se aduce la cunoștința deținutului. Un exemplar se înmânează deținutului, iar celălalt, din care să rezulte luarea la cunoștință, se depune la dosarul individual.","(4) Hotărârea devine executorie:a) la data expirării termenului prevăzut în art. 40 alin. (11) din Lege, dacă deținutul nu a formulat plângere; ... b) la data înregistrării în penitenciar a încheierii judecătorului de supraveghere a privării de libertate sau, după caz, a sentinței instanței de judecată, prin care a fost soluționată plângerea sau contestația deținutului. ...","(5) Dispozițiile art. 88 alin. (2), (4)-(6), (8)-(10) și art. 89 alin. (2) se aplică în mod corespunzător.","(6) În cazul în care intervine o nouă condamnare la o pedeapsă privativă de libertate, schimbarea ori menținerea regimului de executare se face ținând cont de criteriile prevăzute la art. 88 alin. (1)."],"number":"Art. 91"},
    {"heading":"Individualizarea regimurilor de executare a pedepselor privative de libertate","id":"hg157-92","intro":"(1) Individualizarea regimului de executare a pedepselor privative de libertate urmărește planificarea demersurilor recuperative destinate îmbunătățirii statusului educațional, psihosocial și pregătirii deținutului pentru reintegrare socială, în baza activităților și programelor educative, de asistență psihologică și asistență socială consemnate în Planul individualizat de evaluare și intervenție educativă și terapeutică.","items":["(2) Recomandările din Planul individualizat de evaluare și intervenție educativă și terapeutică, completate de către specialiștii sectorului reintegrare socială, consecutiv evaluărilor multidisciplinare inițiale, sunt aprobate în cadrul comisiei prevăzute de art. 32 din Lege, la stabilirea regimului de executare.","(3) În stabilirea recomandărilor din Planul individualizat de evaluare și intervenție educativă și terapeutică se au în vedere nevoile deținutului, identificate din perspectivă multidisciplinară, precum și ariile de intervenție prioritare, raportat la specificul regimului de executare a pedepselor privative de libertate.","(4) Programele și activitățile consemnate în Planul individualizat de evaluare și intervenție educativă și terapeutică sunt aduse la cunoștința deținutului și devin obligatorii pentru acesta, după luarea la cunoștință și semnarea angajamentului de participare.","(5) Planul individualizat de evaluare și intervenție educativă și terapeutică este revizuit la schimbarea regimului de executare a pedepsei privative de libertate și ori de câte ori este necesar, în condițiile alin. (2) și (3)."],"number":"Art. 92"},
    {"heading":"Individualizarea regimurilor de executare a pedepselor privative de libertate în cazul tinerilor","id":"hg157-93","intro":"Tinerii execută pedepsele privative de libertate în penitenciare anume destinate ori în secții sau spații special amenajate, pentru a li se asigura protecția și asistența pe plan social, școlar, educativ, profesional, psihologic, medical și fizic, care le sunt necesare potrivit vârstei, sexului și personalității fiecăruia.","items":[],"number":"Art. 93"},
    {"heading":"Documentele pe care le conține dosarul individual la primirea în locul de deținere","id":"hg157-97","intro":"(1) Deținuții sunt primiți în locurile de deținere în baza mandatului de executare a pedepsei închisorii sau detențiunii pe viață, în original sau în forma primită de la instanța de judecată prin fax, poștă electronică ori prin orice mijloc în măsură să permită stabilirea autenticității, în conformitate cu art. 556 alin. (2^1) din Codul de procedură penală, semnată, datată și ștampilată de organul de poliție care îl pune în executare, după stabilirea identității acestora și verificarea valabilității și autenticității documentelor prevăzute după caz, la alin. (2), (4)-(8). Originalul mandatului de executare a pedepsei închisorii sau detențiunii pe viață se înaintează locului de deținere într-un termen rezonabil, dar nu mai mult de 20 de zile lucrătoare.","items":["(2) Deținuții sunt primiți cu dosarele individuale întocmite de organele de executare a mandatului de executare a pedepselor privative de libertate, ce conțin următoarele documente:a) mandatul de executare a pedepsei privative de libertate, în original sau în forma primită de la instanța de judecată prin fax, poștă electronică ori prin orice mijloc în măsură să permită stabilirea autenticității, în conformitate cu art. 556 alin. (2^1) din Codul de procedură penală, semnată, datată și ștampilată de organul de poliție care îl pune în executare; ... b) actul de identitate valabil sau procesul-verbal de stabilire a identității întocmit de organul de executare; ... c) copia procesului-verbal privind data și ora la care a fost înmânat deținutului mandatul de executare; ... d) adresa de predare a deținutului. ...","(3) Dacă mandatul de executare conține erori materiale, dar permite identificarea persoanei și stabilirea măsurii dispuse în raport cu datele de identificare existente în evidențele organelor de poliție și dispozitivul hotărârii instanței de judecată, administrația penitenciarului primește persoana arătată în mandat, urmând ca organul de poliție ce execută măsura să remită mandatul rectificat după primirea acestuia de la instanța de judecată.","(4) În situația în care deținutul este depus prin intermediul centrelor de reținere și arestare preventivă, dosarul individual va cuprinde: mandatul de executare a pedepsei privative de libertate, copia cazierului judiciar, procesul-verbal de introducere în arest, fișa de cunoaștere individuală, fișa medicală, acte de identitate sau proces-verbal de identificare, fotografie față și profil, fișă dactiloscopică, adresa de predare a deținutului și, după caz, copia hotărârii de condamnare, dacă a fost comunicată de instanța de judecată organului de poliție.","(5) Fișa de cunoaștere individuală cuprinde mențiuni privind comportamentul persoanei private de libertate pe perioada deținerii în centrul de reținere și arestare preventivă, respectiv a arestului la domiciliu, dacă a fost condamnată anterior pentru apartenența la grupări de criminalitate organizată sau teroriste, dacă a fost dată în urmărire, dacă s-a opus reținerii sau arestării, dacă declară că a fost consumatoare de droguri sau dacă în cauza în care a fost condamnată s-a sustras arestului la domiciliu sau controlului judiciar.","(6) În situația în care deținutul a fost subiect al arestului la domiciliu, dosarul individual cuprinde: mandatul de executare a pedepsei privative de libertate în original ori în forma primită de la instanța de judecată prin fax, poștă electronică sau prin orice mijloc în măsură să permită stabilirea autenticității, în conformitate cu art. 556 alin. (2^1) din Codul de procedură penală, semnată, datată și ștampilată de organul de poliție care îl pune în executare, copia cazierului judiciar, fișa de cunoaștere individuală, acte de identitate sau proces-verbal de identificare, adresa de predare a deținutului și, după caz, copia hotărârii de condamnare, dacă a fost comunicată de instanța de judecată organului de poliție.","(7) Pentru primirea deținuților în penitenciarele-spital este necesară recomandarea de internare din partea medicului specialist sau o dispoziție a organului judiciar. În caz de urgență se va proceda la internarea deținutului în cea mai apropiată unitate spitalicească din rețeaua publică.","(8) Administrația locului de deținere poate respinge motivat primirea deținuților în cazul în care nu sunt îndeplinite condițiile prevăzute de alin. (1), (2), (4) și (6).","(9) În cazul în care la primirea în locul de deținere nu sunt îndeplinite condițiile prevăzute de alin. (5), penitenciarul va primi deținutul, urmând ca documentele care trebuiau să îl însoțească să fie transmise în termen de 20 zile lucrătoare."],"number":"Art. 97"},
    {"heading":"Transferarea deținuților","id":"hg157-108","intro":"(1) Comisia prevăzută la art. 32 din Lege face propuneri de transfer Administrației Naționale a Penitenciarelor, în următoarele situații:a) stabilirea sau schimbarea regimului de executare a pedepselor privative de libertate în situația în care acesta nu se încadrează în profilul unității; ... b) depășirea capacității de cazare a penitenciarului; ... c) înscrierea deținuților la cursuri de formare profesională ori de instruire școlară; ... d) folosirea deținuților la muncă, la activități de educație și de asistență psihologică și asistență socială; ... e) în cazul deținuților pentru care măsurile de siguranță, de asigurare a ordinii și disciplinei la nivelul penitenciarului sunt neîndestulătoare; ... f) pentru încheierea căsătoriei; ... g) alte motive temeinic justificate. ...","items":["(2) Deținuții pot formula cereri de transfer în alt penitenciar. În cazul în care cererile de transfer sunt transmise Administrației Naționale a Penitenciarelor, acestea se remit administrației penitenciarului, în vederea avizării de către comisia prevăzută de art. 32 din Lege.","(3) Cererilor formulate de alte persoane sau organizații nonguvernamentale li se vor da curs doar în măsura în care acestea sunt însușite de către deținuți.","(4) Transferarea deținuților la un alt penitenciar se face conform profilării penitenciarelor, stabilite prin decizia directorului general al Administrației Naționale a Penitenciarelor prevăzută la art. 45 alin. (1) din Lege, și va ține cont, de regulă, ca penitenciarul să fie situat cât mai aproape de localitatea de domiciliu a acestora.","(5) Dispozițiile art. 103 se aplică în mod corespunzător.","(6) Prin decizia directorului general al Administrației Naționale a Penitenciarelor se stabilesc limitele competenței și responsabilitățile penitenciarelor cu rol de coordonare zonală, în aplicarea art. 12 alin. (2) lit. k)-m).","(7) În cazul prevăzut la art. 45 alin. (6) din Lege, informarea judecătorului de supraveghere a privării de libertate se face prin adresă scrisă sau prin avizarea adresei de solicitare a transferului în centrul de reținere și arestare preventivă.","(8) Inițierea de către deținuți a unor cauze penale ori civile pentru ei sau pentru alții, în scopul menținerii ori transferării într-un penitenciar, constatată de către instanța de judecată ca fiind un abuz de drept, constituie abatere disciplinară foarte gravă."],"number":"Art. 108"},
    {"heading":"Activități determinate de punerea în libertate","id":"hg157-116","intro":"(1) Punerea în libertate a deținuților se face de către directorul locului de deținere, la expirarea duratei pedepsei privative de libertate, la data rămânerii definitive a hotărârii prin care s-a dispus liberarea condiționată, precum și la orice altă dată hotărâtă de organele judiciare competente în situațiile anume prevăzute de lege, comunicând despre acest fapt organelor judiciare prevăzute la art. 53 alin. (1) din Lege.","items":["(2) Administrația penitenciarului solicită instanței de judecată informații în caz de nelămuriri cu privire la situația juridică a deținuților, ori de câte ori este necesar.","(3) Cu ocazia liberării, deținutului i se înmânează biletul de liberare, documentele personale și, la cerere, fotocopii de pe actele din dosarul individual, inclusiv de pe actele medicale, precum și o scrisoare medicală către medicul de familie. De asemenea, după restituirea către administrația locului de deținere a bunurilor încredințate, deținutului i se înmânează bunurile și sumele de bani, deținute conform dispozițiilor legale și aflate la locul de deținere, inclusiv documentele referitoare la contul său.","(4) Contravaloarea serviciilor de fotocopiere efectuate în condițiile alin. (3) este suportată de deținut.","(5) Punerea în libertate a deținutului se realizează fără întârziere, după efectuarea activităților prevăzute la art. 53 alin. (1) și (3) din Lege.","(6) Organul de poliție sesizat de administrația penitenciarului, în condițiile art. 53 alin. (2) din Lege, este cel din raza teritorială a localității unde se deplasează deținutul în cazul permisiunii de ieșire din penitenciar și al desfășurării activităților de către deținuții din regim deschis, în situația în care aceștia se deplasează neînsoțiți în exteriorul locului de deținere, și Inspectoratul General al Poliției Române, în situația producerii unei evadări.","(7) Organul de poliție sesizat de administrația penitenciarului în situațiile prevăzute la alin. (6) întreprinde măsurile necesare în vederea informării persoanei vătămate, inclusiv prin cooperarea cu organele de poliție de la adresa indicată de persoana vătămată sau de la domiciliul ori reședința acesteia.","(8) Punerea în libertate a deținuților cu afecțiuni psihice se comunică direcției de sănătate publică din județul în raza căruia își au domiciliul, în vederea continuării tratamentului medical.","(9) Numele deținuților de cetățenie străină sau apatrizi care urmează să fie puși în libertate se comunică, în scris, la Inspectoratul General pentru Imigrări din cadrul Ministerului Afacerilor Interne, cu 5 zile înainte de data expirării pedepsei privative de libertate. În cazul punerii în libertate înainte de expirarea duratei condamnării, comunicarea se face în ziua primirii adresei de punere în libertate."],"number":"Art. 116"},
    {"heading":"Dreptul la consultarea documentelor cu caracter personal","id":"hg157-127","intro":"(1) Deținutul, apărătorul acestuia sau oricare altă persoană, cu acordul scris al deținutului, are acces la dosarul individual.","items":["(2) Deținutul poate obține, la cerere, contra cost, într-un număr de exemplare justificat, fotocopii ale documentelor din dosarul individual.","(3) Dacă deținuții nu au dispus în ultimele 30 de zile de mijloacele bănești necesare, în lei sau valută, care pot fi utilizate pe perioada executării pedepsei, cheltuielile prevăzute la alin. (2) sunt suportate de către administrația penitenciarului, dispozițiile art. 60 alin. (4) din Lege aplicându-se în mod corespunzător.","(4) Apărătorul sau oricare altă persoană, cu acordul scris al deținutului, poate obține, contra cost, o fotocopie a documentelor din dosarul individual.","(5) Organele abilitate potrivit legii au acces la dosarul individual fără acordul deținutului.","(6) Consultarea dosarului individual se face în prezența unei persoane desemnate de directorul penitenciarului.","(7) În situația în care este necesară anonimizarea datelor personale ale unor terțe persoane, se remit fotocopii modificate deținutului, apărătorului acestuia sau altei persoane."],"number":"Art. 127"},
    {"heading":"Dreptul de a vota","id":"hg157-169","intro":"(1) Administrația penitenciarului, în colaborare cu birourile electorale și serviciile publice comunitare de evidență a persoanelor, asigură condițiile necesare exercitării dreptului de a vota deținuților cărora nu le-a fost interzis prin hotărârea de condamnare acest drept, potrivit legii.","items":["(2) Administrația penitenciarului ține evidența cazurilor în care deținuții au renunțat la dreptul de a vota."],"number":"Art. 169"},
    {"heading":"Categorii de deținuți discutați în comisia pentru liberare condiționată","id":"hg157-204","intro":"(1) În comisia pentru liberare condiționată se analizează, în vederea propunerii pentru acordarea liberării condiționate, la împlinirea fracțiunilor de executat conform Codului penal, deținuții din regimul semideschis și deschis, care:a) sunt condamnați la una sau mai multe pedepse privative de libertate; ... b) sunt condamnați la una sau mai multe pedepse privative de libertate și sunt cercetați în altă cauză. ...","items":["(2) La solicitarea instanței de judecată, în comisia pentru liberare condiționată se analizează și deținuții condamnați la una sau mai multe pedepse privative de libertate, care nu au executat fracțiunile prevăzute de Codul penal.","(3) În comisia pentru liberare condiționată se analizează și deținuții care, anterior, nu au îndeplinit condițiile pentru acordarea liberării condiționate, la termenele fixate de instanțele de judecată ori, după caz, de comisia pentru liberare condiționată.","(4) Dispozițiile alin. (1)-(3) se aplică în mod corespunzător și în cazul deținuților condamnați la detențiunea pe viață."],"number":"Art. 204"},
    {"heading":"Metodologia de lucru a comisiei pentru liberare condiționată","id":"hg157-205","intro":"(1) Comisia pentru liberare condiționată se întrunește, de regulă, săptămânal, în condițiile art. 97 alin. (5) din Lege.","items":["(2) Administrația penitenciarului ține evidența zilelor considerate ca executate pe baza muncii depuse și/sau a instruirii școlare și formării profesionale, a datelor de împlinire a fracțiunilor de executat conform Codului penal și a termenelor de analizare în comisia pentru liberare condiționată.","(3) Prin grija serviciului sau biroului evidență deținuți se întocmește partea preconstituită a procesului-verbal prevăzut de art. 97 alin. (6) din Lege, care cuprinde următoarele mențiuni referitoare la deținut:a) datele de stare civilă; ... b) condamnarea și fapta; ... c) descrierea pe scurt a faptei; ... d) modul de calcul al fracțiunilor prevăzute de Codul penal; ... e) antecedentele penale, făcându-se precizarea dacă este sau nu recidivist; ... f) existența vreunui mandat de arestare preventivă sau a unei hotărâri de condamnare în primă instanță; ... g) regimul de executare a pedepsei privative de libertate; ... h) dacă a mai beneficiat sau nu de liberare condiționată; ... i) recompensele acordate și sancțiunile disciplinare aplicate; ... j) dacă a mai fost analizat în comisia pentru liberare condiționată. ...","(4) Criteriile pe baza cărora comisia își formulează propunerile sunt cele prevăzute de art. 97 alin. (3) și (4) din Lege.","(5) Propunerea de liberare condiționată este cuprinsă în procesul-verbal prevăzut la alin. (3), semnat și motivat. În cazul în care se constată că nu sunt îndeplinite condițiile prevăzute de lege pentru liberarea condiționată, în procesul-verbal se menționează și termenul fixat pentru reexaminare, în condițiile art. 97 alin. (11) din Lege. Persoanei condamnate i se aduce la cunoștință, sub semnătură, propunerea comisiei.","(6) Procesul-verbal cu propunerea de liberare condiționată, împreună cu documentele pe care aceasta se sprijină, și, după caz, cu recomandările consilierului de probațiune formulate în condițiile art. 97 alin. (7) din Lege sunt înaintate judecătoriei în a cărei circumscripție se află penitenciarul."],"number":"Art. 205"},
    {"heading":"Informarea deținutului cu privire la neîndeplinirea condițiilor pentru liberare condiționată","id":"hg157-206","intro":"În cazul în care comisia pentru liberare condiționată constată că deținutul nu întrunește condițiile pentru a fi liberat condiționat, i se pune în vedere acestuia, sub semnătură, că se poate adresa direct cu cerere instanței de judecată.","items":[],"number":"Art. 206"},
    {"heading":"Revocarea liberării condiționate","id":"hg157-207","intro":"Persoanele care au fost încarcerate în vederea executării restului de pedeapsă, în urma revocării liberării condiționate pentru nerespectarea măsurilor de supraveghere ori neexecutarea obligațiilor, execută restul de pedeapsă conform art. 104 alin. (1) din Codul penal.","items":[],"number":"Art. 207"},
    {"heading":"Categoriile de persoane internate cărora li se aplică regimul închis","id":"hg157-301","intro":"(1) Regimul închis se aplică persoanelor internate față de care s-a dispus executarea măsurii educative a internării într-un centru de detenție pentru o perioadă mai mare de 3 ani.","items":["(2) În mod excepțional, regimul închis se poate aplica și persoanelor internate față de care s-a dispus executarea măsurii educative a internării într-un centru de detenție pentru o perioadă mai mică de 3 ani, în conformitate cu prevederile art. 150 alin. (2) din Lege, în funcție de natura și modul de săvârșire a infracțiunii, persoana internatului, conduita acestuia de natură a afecta siguranța centrului.","(3) Regimul închis se poate aplica și persoanelor internate aflate în situațiile prevăzute la art. 152 alin. (2) din Lege, ținându-se cont de restul rămas neexecutat din durata măsurii internării și de prevederile alin. (2).","(4) Regimul închis se aplică și persoanelor internate, clasificate inițial în regim deschis care au comis o abatere disciplinară foarte gravă sau abateri disciplinare grave, repetate, și care, prin conduita lor, afectează desfășurarea normală a activităților în centru."],"number":"Art. 301"},
    {"heading":"Categoriile de persoane internate cărora li se aplică regimul deschis","id":"hg157-304","intro":"(1) Regimul deschis se aplică persoanelor internate față de care s-a dispus executarea măsurii educative a internării într-un centru de detenție pentru o perioadă mai mică de 3 ani, în conformitate cu prevederile art. 150 alin. (1) din Lege.","items":["(2) În mod excepțional, regimul deschis se poate aplica și persoanelor internate față de care s-a dispus executarea măsurii educative a internării într-un centru de detenție pentru o perioadă mai mare de 3 ani, în conformitate cu prevederile art. 149 alin. (2) din Lege, în funcție de natura și modul de săvârșire a infracțiunii, persoana internatului, conduita acestuia până la stabilirea regimului de executare.","(3) Regimul deschis se poate aplica și persoanelor internate aflate în situațiile prevăzute la art. 152 alin. (2) din Lege, ținându-se cont de restul rămas neexecutat din durata măsurii internării și de prevederile alin. (2).","(4) Regimul deschis se aplică și persoanelor internate clasificate inițial în regimul închis care au avut o bună conduită și au făcut eforturi serioase pentru reintegrare socială."],"number":"Art. 304"},
    {"heading":"Liberarea persoanelor internate și înlocuirea măsurii internării într-un centru cu măsura educativă a asistării zilnice","id":"hg157-337","intro":"(1) În vederea aplicării art. 179 și 180 din Lege, consiliul educativ, respectiv comisia prevăzută de art. 146 din Lege, de regulă, se întrunește săptămânal, cu participarea judecătorului de supraveghere a privării de libertate, în calitate de președinte, și a unui consilier de probațiune din cadrul serviciului de probațiune competent potrivit legii, în circumscripția căruia se află centrul.","items":["(2) Administrația centrului ține evidența datei de împlinire a fracțiunilor de executat potrivit art. 124 și 125 din Codul penal.","(3) Prin grija structurii de evidență se întocmește partea preconstituită a procesului-verbal ce urmează a fi înaintat instanței de judecată. Partea preconstituită a procesului-verbal cuprinde următoarele mențiuni referitoare la persoana internată:a) date de stare civilă; ... b) condamnarea și fapta; ... c) descrierea pe scurt a faptei; ... d) antecedente penale; ... e) existența vreunui mandat de arestare preventivă sau hotărâre judecătorească în primă instanță. ...","(4) Propunerea membrilor consiliului educativ sau ai comisiei prevăzute de art. 146 din Lege este cuprinsă într-un proces-verbal motivat. Fiecare membru și președintele consiliului educativ sau ai comisiei prevăzute de art. 146 din Lege își exprimă poziția cu privire la oportunitatea înlocuirii măsurii internării într-un centru cu măsura educativă a asistării zilnice sau, după caz, a liberării din centru.","(5) Propunerea consiliului educativ sau a comisiei prevăzute de art. 146 din Lege, împreună cu documentele pe care aceasta se sprijină, sunt înaintate, prin grija serviciului sau biroului evidență deținuți, instanței în a cărei circumscripție se află centrul, corespunzătoare în grad instanței de executare.","(6) În cazul în care consiliul educativ sau comisia prevăzută de art. 146 din Lege constată că persoana internată nu întrunește condițiile pentru înlocuirea măsurii internării într-un centru cu măsura educativă a asistării zilnice, sau, după caz, cu liberarea din centru, i se pune în vedere acesteia, sub semnătură, că se poate adresa direct cu cerere instanței de judecată."],"number":"Art. 337"},
    {"heading":"Continuarea executării măsurii educative privative de libertate în penitenciar","id":"hg157-338","intro":"(1) Consiliul educativ sau comisia prevăzută la art. 146 din Lege, cu participarea judecătorului de supraveghere a privării de libertate, în calitate de președinte, și a asistentului social, din oficiu sau la sesizarea comisiei de disciplină, analizează situația persoanei internate și poate propune continuarea executării măsurii educative privative de libertate în penitenciar, dacă aceasta a săvârșit una dintre faptele următoarele:a) inițierea de acțiuni care conduc la nefrecventarea sau refuzul său constant, precum și al altor persoane internate de a participa la cursuri de instruire școlară și formare profesională, la programe și activități educative, de asistență psihologică și asistență socială; ... b) introducerea, deținerea sau traficul de arme, materiale explozive, droguri, substanțe toxice sau alte obiecte și substanțe care pun în pericol siguranța centrului, a misiunilor sau a persoanelor; ... c) nerespectarea interdicțiilor prevăzute la art. 82 lit. a)-c) din Lege; ... d) nerespectarea, în mod repetat, a interdicțiilor prevăzute la art. 82 lit. f) și h) din Lege. ...","items":["(2) Dispozițiile art. 337 alin. (3)-(5) se aplică în mod corespunzător.","(3) În termen de maximum 72 de ore de la rămânerea definitivă a hotărârii prin care s-a dispus continuarea executării măsurii educative privative de libertate în penitenciar, persoana internată este transferată în penitenciarul stabilit de directorul general al Administrației Naționale a Penitenciarelor."],"number":"Art. 338"},
    {"heading":"Regimul de executare a continuării măsurii educative privative de libertate în penitenciar","id":"hg157-339","intro":"(1) Continuarea măsurii educative privative de libertate în penitenciar se execută în secții anume destinate din locurile de deținere stabilite prin decizia directorului general al Administrației Naționale a Penitenciarelor prevăzută la art. 45 alin. (1) din Lege.","items":["(2) Dispozițiile art. 64 și ale art. 68-72, respectiv ale art. 80 și art. 84-87 și cele referitoare la acordarea drepturilor persoanelor condamnate în regimul închis, respectiv deschis se aplică în mod corespunzător regimului de executare în care sunt incluse.","(3) Administrația penitenciarului și comisiile prevăzute de art. 32 alin. (1), art. 97 alin. (2), art. 98 alin. (2) și art. 103 alin. (2) din Lege sunt competente să dispună în conformitate cu prevederile din cap. IV-X, titlul V, care se aplică în mod corespunzător."],"number":"Art. 339"},
    {"heading":"Regimul de executare a măsurii educative privative de libertate în penitenciar","id":"hg157-340","intro":"Prevederile art. 339 se aplică în mod corespunzător și persoanelor pentru care instanța de judecată a dispus executarea măsurii educative într-un penitenciar, potrivit art. 134 din Legea nr. 286/2009 privind Codul penal.","items":[],"number":"Art. 340"}
  ]}
];

