questions.push(
  {id:1001,law:"l145",official:"anp2024",ref:"ANP 2024 · Legea nr. 145/2019, art. 119",q:"Polițistul de penitenciare are următoarea obligație:",a:["să uzeze de funcție pentru rezolvarea intereselor personale","să intervină în lucrări care nu îi sunt repartizate","să fie disciplinat, respectuos și onest față de șefi, colegi sau subalterni și să respecte ierarhia"],c:2,e:"Răspunsul oficial din baremul ANP este varianta c). Formularea istorică a variantei folosește «onest», însă art. 119 lit. e) din forma consolidată folosește termenul «corect». Învață formularea actuală a legii."},
  {id:1002,law:"l254",official:"anp2024",ref:"ANP 2024 · Legea nr. 254/2013, art. 35 alin. (1)",q:"Potrivit baremului, regimul de maximă siguranță nu se aplică:",a:["persoanelor încadrate în gradul II de invaliditate","femeilor însărcinate sau care au în îngrijire un copil în vârstă de până la un an","persoanelor care au împlinit vârsta de 60 de ani"],c:1,e:"Baremul oficial indică varianta b), iar răspunsul rămâne corect. Atenție: varianta c) este un distractor fals; art. 35 folosește pragul de 65 de ani, nu 60 de ani."},
  {id:1003,law:"cp",official:"anp2024",ref:"ANP 2024 · Cod penal, art. 53",q:"Pedepsele principale sunt:",a:["detențiunea pe viață, închisoarea și amenda","detențiunea pe viață, închisoarea și arestul la domiciliu","detențiunea pe viață și închisoarea"],c:0,e:"Răspuns oficial: a)."},
  {id:1004,law:"l254",official:"anp2024",ref:"ANP 2024 · Legea nr. 254/2013, art. 160",q:"Punerea în libertate a minorului din centrul educativ sau centrul de detenție se comunică:",a:["instanței de executare, familiei sau tutorelui legal","instanței de executare, familiei sau reprezentantului legal","familiei sau reprezentantului legal"],c:2,e:"Baremul oficial indică varianta c)."},
  {id:1005,law:"hg157",official:"anp2024",ref:"ANP 2024 · HG nr. 157/2016, art. 108",q:"Comisia prevăzută la art. 32 din Legea nr. 254/2013 poate propune transferul ANP:",a:["în vederea acordării vizitei intime","când măsurile de siguranță, ordine și disciplină la nivelul penitenciarului sunt neîndestulătoare","pentru stabilirea regimului provizoriu când persoana nu se încadrează în profilul unității"],c:1,e:"Răspuns oficial: b)."},
  {id:1006,law:"hg157",official:"anp2024",ref:"ANP 2024 · HG nr. 157/2016, art. 338 alin. (3)",q:"După rămânerea definitivă a hotărârii de continuare a măsurii educative în penitenciar, persoana este transferată:",a:["în maximum 72 de ore, în penitenciarul stabilit de directorul general al ANP","în maximum 48 de ore, în penitenciarul stabilit de directorul penitenciarului","în maximum 48 de ore, în penitenciarul stabilit de directorul general al ANP"],c:0,e:"Răspuns oficial: a)."},
  {id:1007,law:"cpp",official:"anp2024",ref:"ANP 2024 · Cod procedură penală, art. 399 alin. (3)",q:"Instanța dispune punerea de îndată în libertate a inculpatului arestat preventiv atunci când pronunță:",a:["o pedeapsă cu închisoarea, cu amânarea aplicării pedepsei","o pedeapsă cu amendă, care nu însoțește pedeapsa închisorii","pedeapsa închisorii de cel mult un an"],c:1,e:"Răspuns oficial: b)."},
  {id:1008,law:"l254",official:"anp2024",ref:"ANP 2024 · Legea nr. 254/2013, art. 96 alin. (1)",q:"Pentru participarea la cursurile de școlarizare aferente învățământului general obligatoriu se consideră executate:",a:["30 de zile pentru absolvirea unui an școlar","20 de zile pentru absolvirea unui an școlar","30 de zile pentru absolvirea unui curs de calificare ori recalificare"],c:0,e:"Răspuns oficial: a)."},
  {id:1009,law:"omj2188",official:"anp2024",ref:"ANP 2024 · OMJ nr. 2188/C/2022, art. 112 alin. (1)",q:"În cazul evadării unei persoane private de libertate, lucrătorul structurii evidență:",a:["pune documentarul penal la dispoziția inspectoratului de poliție","face mențiunile corespunzătoare în registrul de evidență a termenelor","informează de îndată instanța de executare"],c:1,e:"Răspuns oficial: b)."},
  {id:1010,law:"cp",official:"anp2024",ref:"ANP 2024 · Cod penal, art. 125 alin. (4)",q:"După executarea a cel puțin jumătate din durata internării, instanța poate dispune, în condițiile legii:",a:["înlocuirea internării cu asistarea zilnică pentru perioada neexecutată, dar nu mai mult de 6 luni, dacă persoana nu a împlinit 18 ani","înlocuirea internării cu asistarea zilnică, dar nu mai mult de 4 luni","liberarea din centrul educativ dacă persoana a împlinit 18 ani"],c:0,e:"Răspuns oficial: a)."}
);


